-- Probe of the AWR Capacity APEX app that needs no APEX; generated by apex/build.py --smoke.
set appinfo off
set appinfo "AWRCAP/apex/test/apex_probe.sql"
-- Run from the repository root in the schema that holds the suite (or as SYSDBA with
-- CURRENT_SCHEMA set to it):  @apex/test/apex_probe.sql
-- The table AWRCAP_PROBE_COLL stands in for APEX_COLLECTIONS: the loader queries of the
-- application fill it, then every region query, LOV and default of every page runs
-- against it under the scenarios of the smoke harness, items bound with DBMS_SQL, and
-- each collection is compared with its source view. The table is dropped at the end.
-- Prints one line per statement and RESULT: at the end; exits non-zero on a failure.
-- Not covered: the import into APEX and what a browser renders.
set serveroutput on size unlimited format wrapped feedback off verify off define off
whenever sqlerror exit failure rollback
variable probe_fail number
begin
  execute immediate 'drop table awrcap_probe_coll purge';
exception when others then
  if sqlcode <> -942 then raise; end if;
end;
/
create table awrcap_probe_coll (
  collection_name varchar2(255), seq_id number,
  n001 number, n002 number, n003 number, n004 number, n005 number,
  d001 date, d002 date, d003 date, d004 date, d005 date,
  c001 varchar2(4000), c002 varchar2(4000), c003 varchar2(4000), c004 varchar2(4000), c005 varchar2(4000),
  c006 varchar2(4000), c007 varchar2(4000), c008 varchar2(4000), c009 varchar2(4000), c010 varchar2(4000),
  c011 varchar2(4000), c012 varchar2(4000), c013 varchar2(4000), c014 varchar2(4000), c015 varchar2(4000),
  c016 varchar2(4000), c017 varchar2(4000), c018 varchar2(4000), c019 varchar2(4000), c020 varchar2(4000),
  c021 varchar2(4000), c022 varchar2(4000), c023 varchar2(4000), c024 varchar2(4000), c025 varchar2(4000),
  c026 varchar2(4000), c027 varchar2(4000), c028 varchar2(4000), c029 varchar2(4000), c030 varchar2(4000),
  c031 varchar2(4000), c032 varchar2(4000), c033 varchar2(4000), c034 varchar2(4000), c035 varchar2(4000),
  c036 varchar2(4000), c037 varchar2(4000), c038 varchar2(4000), c039 varchar2(4000), c040 varchar2(4000),
  c041 varchar2(4000), c042 varchar2(4000), c043 varchar2(4000), c044 varchar2(4000), c045 varchar2(4000),
  c046 varchar2(4000), c047 varchar2(4000), c048 varchar2(4000), c049 varchar2(4000), c050 varchar2(4000));
declare
  type t_state is table of varchar2(4000) index by varchar2(30);
  type t_names is table of varchar2(30);
  g_items constant t_names := t_names('P0_TARGET', 'P0_DB', 'P0_TBSPC', 'P0_FROM', 'P0_TO', 'P0_KIND', 'P0_SEV');
  g_state t_state;
  g_loaded t_state;
  l_pass pls_integer := 0;
  l_fail pls_integer := 0;
  function v(p_item in varchar2) return varchar2 is
  begin
    return case when g_state.exists(p_item) then g_state(p_item) end;
  end;
  procedure set_state(p_item in varchar2, p_value in varchar2) is
  begin
    g_state(p_item) := p_value;
  end;
  procedure passed(p_ok in boolean) is
  begin
    if p_ok then l_pass := l_pass + 1; else l_fail := l_fail + 1; end if;
  end;
  -- Binds the items the statement names, fetches every row and every column.
  procedure run(p_sql in varchar2, p_rows out number, p_first out varchar2) is
    l_cur integer := dbms_sql.open_cursor;
    l_cols dbms_sql.desc_tab2;
    l_n integer;
    l_val varchar2(4000);
    l_ignore integer;
    -- without its string literals: a link's item list ('..:P0_DB:..') names no bind
    l_bare varchar2(32767) := regexp_replace(p_sql, '''[^'']*''', '''''');
  begin
    dbms_sql.parse(l_cur, p_sql, dbms_sql.native);
    for i in 1 .. g_items.count loop
      if regexp_like(l_bare, ':' || g_items(i) || '([^A-Za-z0-9_]|$)') then
        dbms_sql.bind_variable(l_cur, ':' || g_items(i), v(g_items(i)));
      end if;
    end loop;
    dbms_sql.describe_columns2(l_cur, l_n, l_cols);
    for i in 1 .. l_n loop
      dbms_sql.define_column(l_cur, i, l_val, 4000);
    end loop;
    l_ignore := dbms_sql.execute(l_cur);
    p_rows := 0;
    while dbms_sql.fetch_rows(l_cur) > 0 loop
      p_rows := p_rows + 1;
      for i in 1 .. l_n loop
        dbms_sql.column_value(l_cur, i, l_val);
        if p_rows = 1 and i = 1 then p_first := l_val; end if;
      end loop;
    end loop;
    dbms_sql.close_cursor(l_cur);
  exception when others then
    if dbms_sql.is_open(l_cur) then dbms_sql.close_cursor(l_cur); end if;
    raise;
  end;
  function pick(p_sql in varchar2) return varchar2 is
    l_rows number;
    l_val varchar2(4000);
  begin
    run(p_sql, l_rows, l_val);
    return l_val;
  end;
  procedure check_query(p_label in varchar2, p_sql in varchar2, p_must in boolean) is
    l_rows number;
    l_val varchar2(4000);
    l_t0 pls_integer := dbms_utility.get_time;
  begin
    run(p_sql, l_rows, l_val);
    dbms_output.put_line(case when p_must and l_rows = 0 then 'FAIL ' else 'ok   ' end || lpad(l_rows, 6) || to_char((dbms_utility.get_time - l_t0) / 100, '990.00') || 's  ' || p_label);
    passed(not (p_must and l_rows = 0));
  exception when others then
    dbms_output.put_line('FAIL  error  ' || p_label || ': ' || sqlerrm);
    passed(false);
  end;
  procedure check_empty(p_label in varchar2, p_sql in varchar2) is
    l_rows number;
    l_val varchar2(4000);
  begin
    run(p_sql, l_rows, l_val);
    dbms_output.put_line(case when l_rows = 0 then 'ok   ' else 'FAIL ' end || lpad(l_rows, 6) || '  ' || p_label);
    passed(l_rows = 0);
  exception when others then
    dbms_output.put_line('FAIL  error  ' || p_label || ': ' || sqlerrm);
    passed(false);
  end;
  procedure drop_all is
  begin
    execute immediate 'delete from awrcap_probe_coll';
    g_loaded.delete;
  end;
  -- create_collection_from_queryb2: the query columns are the slots, by name here.
  procedure load(p_name in varchar2, p_query in varchar2) is
    l_cur integer;
    l_cols dbms_sql.desc_tab2;
    l_n integer;
    l_list varchar2(4000);
    l_t0 pls_integer := dbms_utility.get_time;
  begin
    if g_loaded.exists(p_name) then return; end if;
    g_loaded(p_name) := 'Y';
    l_cur := dbms_sql.open_cursor;
    dbms_sql.parse(l_cur, p_query, dbms_sql.native);
    dbms_sql.describe_columns2(l_cur, l_n, l_cols);
    dbms_sql.close_cursor(l_cur);
    for i in 1 .. l_n loop
      l_list := l_list || ', ' || l_cols(i).col_name;
    end loop;
    execute immediate 'insert into awrcap_probe_coll (collection_name, seq_id' || l_list
      || ') select :name, rownum, q.* from (' || p_query || ') q' using p_name;
    dbms_output.put_line('ok   ' || lpad(sql%rowcount, 6) || to_char((dbms_utility.get_time - l_t0) / 100, '990.00') || 's  load ' || p_name);
    passed(true);
  exception when others then
    if dbms_sql.is_open(l_cur) then dbms_sql.close_cursor(l_cur); end if;
    dbms_output.put_line('FAIL  error  load ' || p_name || ': ' || sqlerrm);
    passed(false);
  end;
  procedure load_page(p_page in pls_integer, p_request in varchar2) is
  begin
    begin
      if p_request = 'REFRESH' then
        drop_all;
      end if;
      if p_page in (1, 5, 2, 3, 6, 4) then
        load('AWRCAP_CONTAINER', q'~select dbid n001, con_dbid n002, cast(null as number) n003, cast(null as number) n004, cast(null as number) n005, cast(null as date) d001, cast(null as date) d002, cast(null as date) d003, cast(null as date) d004, cast(null as date) d005, db_pdb c001, db_name c002, con_name c003, target_name c004 from (select * from capr_container)~');
      end if;
      if p_page in (5) then
        load('AWRCAP_TARGETS', q'~select dbid n001, n_containers n002, age_hours n003, n_gaps n004, collected_snap_id n005, newest_snap d001, last_ok_at d002, last_error_at d003, cast(null as date) d004, cast(null as date) d005, target_name c001, db_name c002, feed c003, host_name c004, db_link c005, enabled c006, is_stale c007, collect_state c008, last_error c009 from (select * from capr_targets)~');
      end if;
      if p_page in (1, 5, 2, 3, 6, 4) then
        load('AWRCAP_SERIES', q'~select value n001, limit_value n002, expected n003, rate_bpd n004, anomaly n005, ts d001, cast(null as date) d002, cast(null as date) d003, cast(null as date) d004, cast(null as date) d005, db c001, kind c002, series c003, unit c004, anomaly_flag c005, to_char(round(pct, 10), 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,''') c006, to_char(round(gap, 10), 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,''') c007, to_char(round(z, 10), 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,''') c008, to_char(round(threshold, 10), 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,''') c009, to_char(round(delta_bytes, 10), 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,''') c010, to_char(round(busy_p95, 10), 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,''') c011, to_char(round(busy_peak_pct, 10), 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,''') c012 from (select * from capr_series_points)~');
      end if;
      if p_page in (2, 3, 6) then
        load('AWRCAP_FORECAST', q'~select value n001, lo n002, hi n003, limit_value n004, horizon_days n005, ts d001, cast(null as date) d002, cast(null as date) d003, cast(null as date) d004, cast(null as date) d005, db c001, kind c002, series c003, unit c004, method c005, quality c006, to_char(round(pct, 10), 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,''') c007 from (select * from capr_forecast_points)~');
      end if;
      if p_page in (1, 5, 2, 3, 6) then
        load('AWRCAP_FIT', q'~select value n001, limit_value n002, pct n003, days_to_full n004, sev_rank n005, last_day d001, cast(null as date) d002, cast(null as date) d003, cast(null as date) d004, cast(null as date) d005, db c001, kind c002, series c003, unit c004, method c005, quality c006, sev c007, limit_source c008, to_char(round(slope_per_day, 10), 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,''') c009, to_char(round(r2, 10), 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,''') c010, to_char(round(days_to_full_lo, 10), 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,''') c011, to_char(round(days_to_full_hi, 10), 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,''') c012, to_char(round(accel, 10), 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,''') c013, to_char(round(train_n, 10), 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,''') c014 from (select * from capr_fit)~');
      end if;
      if p_page in (1, 2, 3, 4) then
        load('AWRCAP_ANOMALIES', q'~select value n001, expected n002, threshold n003, z n004, sev_rank n005, ts d001, obs_day d002, cast(null as date) d003, cast(null as date) d004, cast(null as date) d005, db c001, kind c002, series c003, anomaly_kind c004, anomaly_flag c005, unit c006, sev c007, message c008, to_char(round(shift_pct, 10), 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,''') c009, to_char(round(rate_bpd, 10), 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,''') c010 from (select * from capr_anomalies)~');
      end if;
      if p_page in (1, 5, 2, 3, 4) then
        load('AWRCAP_ALERTS', q'~select sev_rank n001, value n002, threshold n003, cast(null as number) n004, cast(null as number) n005, day_dt d001, cast(null as date) d002, cast(null as date) d003, cast(null as date) d004, cast(null as date) d005, severity c001, kind c002, db_pdb c003, series_key c004, unit c005, message c006 from (select * from capr_alerts)~');
      end if;
      if p_page in (6) then
        load('AWRCAP_MEM_VERDICT', q'~select instance_number n001, area_rank n002, current_bytes n003, suggested_bytes n004, change_pct n005, window_start d001, window_end d002, cast(null as date) d003, cast(null as date) d004, cast(null as date) d005, db_pdb c001, area c002, area_label c003, mem_mode c004, grade c005, reason c006, reason_text c007, actionable c008, current_size c009, suggested_size c010, suggested_param c011, exceeds_host_ram c012, exceeds_sga c013, headline c014, to_char(round(n_evidence, 10), 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,''') c015, to_char(round(n_pressure, 10), 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,''') c016, to_char(round(n_days, 10), 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,''') c017, to_char(round(rank_mem, 10), 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,''') c018 from (select * from capr_mem_verdict)~');
      end if;
      if p_page in (6) then
        load('AWRCAP_MEM_EVIDENCE', q'~select instance_number n001, area_rank n002, value n003, threshold n004, rank_ev n005, observed_at d001, cast(null as date) d002, cast(null as date) d003, cast(null as date) d004, cast(null as date) d005, db_pdb c001, area c002, area_label c003, kind c004, signal c005, direction c006, unit c007, evidence_text c008 from (select * from capr_mem_evidence)~');
      end if;
      if p_page in (6) then
        load('AWRCAP_MEM_POINTS', q'~select instance_number n001, bytes n002, min_bytes n003, max_bytes n004, ops n005, ts d001, cast(null as date) d002, cast(null as date) d003, cast(null as date) d004, cast(null as date) d005, db_pdb c001, component c002 from (select p.instance_number, p.component, p.ts, p.bytes, p.min_bytes, p.max_bytes, p.ops, nvl(c.db_pdb, to_char(p.dbid)) db_pdb from capr_mem_comp_points p left join capr_container c on c.dbid = p.dbid and c.con_dbid = p.con_dbid)~');
      end if;
      if p_page in (1, 5, 2, 3, 6, 4) then
        load('AWRCAP_META', q'~select cpu_sat_pct n001, dtf_warn n002, dtf_crit n003, nearfull_warn_pct n004, nearfull_crit_pct n005, loaded_at d001, cast(null as date) d002, cast(null as date) d003, cast(null as date) d004, cast(null as date) d005, to_char(round(series_sat_pct, 10), 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,''') c001, to_char(round(anomaly_report_days, 10), 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,''') c002 from (select max(case when cfg_name = 'cpu_sat_pct' then cfg_value end) cpu_sat_pct, max(case when cfg_name = 'dtf_warn' then cfg_value end) dtf_warn, max(case when cfg_name = 'dtf_crit' then cfg_value end) dtf_crit, max(case when cfg_name = 'nearfull_warn_pct' then cfg_value end) nearfull_warn_pct, max(case when cfg_name = 'nearfull_crit_pct' then cfg_value end) nearfull_crit_pct, max(case when cfg_name = 'series_sat_pct' then cfg_value end) series_sat_pct, max(case when cfg_name = 'anomaly_report_days' then cfg_value end) anomaly_report_days , sysdate loaded_at from cap_config)~');
      end if;
      if p_page in (1, 5, 2, 3, 6, 4) and (v('P0_TARGET') is not null and v('P0_DB') is not null) then
        set_state('P0_DB', pick(q'~with c_cont as (select c001 db_pdb, c002 db_name, c003 con_name, c004 target_name, n001 dbid, n002 con_dbid from awrcap_probe_coll where collection_name = 'AWRCAP_CONTAINER')
    select max(c.db_pdb) val from c_cont c where c.db_pdb = :P0_DB and c.target_name = :P0_TARGET~'));
      end if;
      if p_page in (1, 5, 2, 3, 6, 4) and (v('P0_FROM') is null) then
        set_state('P0_FROM', pick(q'~with c_series as (select c001 db, c002 kind, c003 series, c004 unit, c005 anomaly_flag, d001 ts, n001 value, n002 limit_value, n003 expected, n004 rate_bpd, n005 anomaly, to_number(c006, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') pct, to_number(c007, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') gap, to_number(c008, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') z, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') threshold, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') delta_bytes, to_number(c011, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') busy_p95, to_number(c012, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') busy_peak_pct from awrcap_probe_coll where collection_name = 'AWRCAP_SERIES')
    select to_char(max(s.ts) - 120, 'YYYY-MM-DD') val from c_series s~'));
      end if;
      if p_page in (1, 5, 2, 3, 6, 4) and (v('P0_TO') is null) then
        set_state('P0_TO', pick(q'~with c_series as (select c001 db, c002 kind, c003 series, c004 unit, c005 anomaly_flag, d001 ts, n001 value, n002 limit_value, n003 expected, n004 rate_bpd, n005 anomaly, to_number(c006, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') pct, to_number(c007, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') gap, to_number(c008, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') z, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') threshold, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') delta_bytes, to_number(c011, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') busy_p95, to_number(c012, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') busy_peak_pct from awrcap_probe_coll where collection_name = 'AWRCAP_SERIES')
    select to_char(max(s.ts) + 120, 'YYYY-MM-DD') val from c_series s~'));
      end if;
      if p_page in (2) and (nvl(v('P0_TBSPC'), '-') <> 'ALL') then
        set_state('P0_TBSPC', pick(q'~with c_cont as (select c001 db_pdb, c002 db_name, c003 con_name, c004 target_name, n001 dbid, n002 con_dbid from awrcap_probe_coll where collection_name = 'AWRCAP_CONTAINER'),
    c_fit as (select c001 db, c002 kind, c003 series, c004 unit, c005 method, c006 quality, c007 sev, c008 limit_source, d001 last_day, n001 value, n002 limit_value, n003 pct, n004 days_to_full, n005 sev_rank, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') slope_per_day, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') r2, to_number(c011, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') days_to_full_lo, to_number(c012, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') days_to_full_hi, to_number(c013, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') accel, to_number(c014, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') train_n from awrcap_probe_coll where collection_name = 'AWRCAP_FIT')
    select max(f.db || '|' || f.series) keep (dense_rank first order by case when f.db || '|' || f.series = :P0_TBSPC then 0 else 1 end, f.days_to_full nulls last, f.pct desc nulls last) val
    from c_fit f where f.kind = 'TBSPC' and ((:P0_DB is null or f.db = :P0_DB) and (:P0_TARGET is null or f.db in (select t.db_pdb from c_cont t where t.target_name = :P0_TARGET)))~'));
      end if;
    end;
  end load_page;
  procedure check_page_1(p_demo in boolean) is
  begin
    check_query(q'~p0 P0_TARGET lov~', q'~with c_cont as (select c001 db_pdb, c002 db_name, c003 con_name, c004 target_name, n001 dbid, n002 con_dbid from awrcap_probe_coll where collection_name = 'AWRCAP_CONTAINER')
select c.target_name d, c.target_name r from c_cont c where c.target_name is not null group by c.target_name order by 1~', false);
    check_query(q'~p0 P0_DB lov~', q'~with c_cont as (select c001 db_pdb, c002 db_name, c003 con_name, c004 target_name, n001 dbid, n002 con_dbid from awrcap_probe_coll where collection_name = 'AWRCAP_CONTAINER')
select c.db_pdb d, c.db_pdb r from c_cont c where (:P0_TARGET is null or c.target_name = :P0_TARGET) group by c.db_pdb order by 1~', false);
    check_query(q'~p0 Data~', q'~with c_cont as (select c001 db_pdb, c002 db_name, c003 con_name, c004 target_name, n001 dbid, n002 con_dbid from awrcap_probe_coll where collection_name = 'AWRCAP_CONTAINER'),
c_series as (select c001 db, c002 kind, c003 series, c004 unit, c005 anomaly_flag, d001 ts, n001 value, n002 limit_value, n003 expected, n004 rate_bpd, n005 anomaly, to_number(c006, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') pct, to_number(c007, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') gap, to_number(c008, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') z, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') threshold, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') delta_bytes, to_number(c011, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') busy_p95, to_number(c012, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') busy_peak_pct from awrcap_probe_coll where collection_name = 'AWRCAP_SERIES'),
c_meta as (select n001 cpu_sat_pct, n002 dtf_warn, n003 dtf_crit, n004 nearfull_warn_pct, n005 nearfull_crit_pct, to_number(c001, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') series_sat_pct, to_number(c002, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') anomaly_report_days, d001 loaded_at from awrcap_probe_coll where collection_name = 'AWRCAP_META')
select (select count(distinct s.db) from c_series s where ((:P0_DB is null or s.db = :P0_DB) and (:P0_TARGET is null or s.db in (select t.db_pdb from c_cont t where t.target_name = :P0_TARGET)))) DATABASES, (select to_char(max(s.ts), 'YYYY-MM-DD') from c_series s where ((:P0_DB is null or s.db = :P0_DB) and (:P0_TARGET is null or s.db in (select t.db_pdb from c_cont t where t.target_name = :P0_TARGET)))) LATEST, (select to_char(min(l.ts), 'YYYY-MM-DD') from (select max(s.ts) ts from c_series s where ((:P0_DB is null or s.db = :P0_DB) and (:P0_TARGET is null or s.db in (select t.db_pdb from c_cont t where t.target_name = :P0_TARGET))) group by s.db) l) STALEST, (select to_char(m.loaded_at, 'HH24:MI') from c_meta m) LOADED
from dual~', p_demo);
    check_query(q'~p1 Summary~', q'~with c_cont as (select c001 db_pdb, c002 db_name, c003 con_name, c004 target_name, n001 dbid, n002 con_dbid from awrcap_probe_coll where collection_name = 'AWRCAP_CONTAINER'),
c_series as (select c001 db, c002 kind, c003 series, c004 unit, c005 anomaly_flag, d001 ts, n001 value, n002 limit_value, n003 expected, n004 rate_bpd, n005 anomaly, to_number(c006, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') pct, to_number(c007, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') gap, to_number(c008, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') z, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') threshold, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') delta_bytes, to_number(c011, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') busy_p95, to_number(c012, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') busy_peak_pct from awrcap_probe_coll where collection_name = 'AWRCAP_SERIES'),
c_fit as (select c001 db, c002 kind, c003 series, c004 unit, c005 method, c006 quality, c007 sev, c008 limit_source, d001 last_day, n001 value, n002 limit_value, n003 pct, n004 days_to_full, n005 sev_rank, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') slope_per_day, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') r2, to_number(c011, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') days_to_full_lo, to_number(c012, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') days_to_full_hi, to_number(c013, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') accel, to_number(c014, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') train_n from awrcap_probe_coll where collection_name = 'AWRCAP_FIT'),
c_anom as (select c001 db, c002 kind, c003 series, c004 anomaly_kind, c005 anomaly_flag, c006 unit, c007 sev, c008 message, d001 ts, d002 obs_day, n001 value, n002 expected, n003 threshold, n004 z, n005 sev_rank, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') shift_pct, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') rate_bpd from awrcap_probe_coll where collection_name = 'AWRCAP_ANOMALIES'),
c_alert as (select c001 severity, c002 kind, c003 db_pdb, c004 series_key, c005 unit, c006 message, d001 day_dt, n001 sev_rank, n002 value, n003 threshold from awrcap_probe_coll where collection_name = 'AWRCAP_ALERTS'),
c_meta as (select n001 cpu_sat_pct, n002 dtf_warn, n003 dtf_crit, n004 nearfull_warn_pct, n005 nearfull_crit_pct, to_number(c001, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') series_sat_pct, to_number(c002, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') anomaly_report_days, d001 loaded_at from awrcap_probe_coll where collection_name = 'AWRCAP_META')
select (select count(*) from c_alert a where a.severity = 'CRIT' and ((:P0_DB is null or a.db_pdb = :P0_DB) and (:P0_TARGET is null or a.db_pdb in (select t.db_pdb from c_cont t where t.target_name = :P0_TARGET)))) CRIT, (select count(*) from c_alert a where a.severity = 'WARN' and ((:P0_DB is null or a.db_pdb = :P0_DB) and (:P0_TARGET is null or a.db_pdb in (select t.db_pdb from c_cont t where t.target_name = :P0_TARGET)))) WARN, (select count(*) from c_alert a where a.severity = 'INFO' and ((:P0_DB is null or a.db_pdb = :P0_DB) and (:P0_TARGET is null or a.db_pdb in (select t.db_pdb from c_cont t where t.target_name = :P0_TARGET)))) INFO, (select nvl(to_char(min(f.days_to_full)), '-') from c_fit f where f.kind = 'TBSPC' and ((:P0_DB is null or f.db = :P0_DB) and (:P0_TARGET is null or f.db in (select t.db_pdb from c_cont t where t.target_name = :P0_TARGET)))) DTF, (select count(*) from c_anom a, c_meta m where nvl(a.obs_day, a.ts) > (select max(s.ts) from c_series s) - m.anomaly_report_days and ((:P0_DB is null or a.db = :P0_DB) and (:P0_TARGET is null or a.db in (select t.db_pdb from c_cont t where t.target_name = :P0_TARGET)))) ANOM, (select round(sum(s.value), 1) from c_series s where s.kind = 'SERIES' and s.series = 'DB_SIZE_GB' and ((:P0_DB is null or s.db = :P0_DB) and (:P0_TARGET is null or s.db in (select t.db_pdb from c_cont t where t.target_name = :P0_TARGET))) and s.ts = (select max(x.ts) from c_series x where x.kind = 'SERIES' and x.series = 'DB_SIZE_GB' and x.db = s.db)) DB_GIB
from dual~', false);
    check_query(q'~p1 Current alerts~', q'~with c_cont as (select c001 db_pdb, c002 db_name, c003 con_name, c004 target_name, n001 dbid, n002 con_dbid from awrcap_probe_coll where collection_name = 'AWRCAP_CONTAINER'),
c_alert as (select c001 severity, c002 kind, c003 db_pdb, c004 series_key, c005 unit, c006 message, d001 day_dt, n001 sev_rank, n002 value, n003 threshold from awrcap_probe_coll where collection_name = 'AWRCAP_ALERTS')
select a.severity SEV, case a.severity when 'CRIT' then 't-Badge--danger' when 'WARN' then 't-Badge--warning' when 'INFO' then 't-Badge--info' else 't-Badge--success' end SEV_CSS, a.sev_rank SEV_RANK, a.kind KIND, (select max(t.target_name) from c_cont t where t.db_pdb = a.db_pdb) TARGET, a.db_pdb DB, a.series_key SERIES, a.day_dt DAY, round(a.value, 2) VALUE, round(a.threshold, 2) THRESHOLD, case lower(a.unit) when 'io_per_sec' then 'requests/s' when 'mb_per_sec' then 'MB/s' else a.unit end UNIT, a.message MESSAGE
from c_alert a where ((:P0_DB is null or a.db_pdb = :P0_DB) and (:P0_TARGET is null or a.db_pdb in (select t.db_pdb from c_cont t where t.target_name = :P0_TARGET)))~', p_demo);
    check_query(q'~p1 Worst days to full~', q'~with c_cont as (select c001 db_pdb, c002 db_name, c003 con_name, c004 target_name, n001 dbid, n002 con_dbid from awrcap_probe_coll where collection_name = 'AWRCAP_CONTAINER'),
c_fit as (select c001 db, c002 kind, c003 series, c004 unit, c005 method, c006 quality, c007 sev, c008 limit_source, d001 last_day, n001 value, n002 limit_value, n003 pct, n004 days_to_full, n005 sev_rank, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') slope_per_day, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') r2, to_number(c011, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') days_to_full_lo, to_number(c012, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') days_to_full_hi, to_number(c013, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') accel, to_number(c014, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') train_n from awrcap_probe_coll where collection_name = 'AWRCAP_FIT')
select (select max(t.target_name) from c_cont t where t.db_pdb = f.db) TARGET, f.db DB, f.series TABLESPACE, ('f?p=' || (2) || ':P0_DB,P0_TBSPC:' || f.db || ',' || f.db || '|' || f.series) TABLESPACE_URL, f.sev SEV, case f.sev when 'CRIT' then 't-Badge--danger' when 'WARN' then 't-Badge--warning' when 'INFO' then 't-Badge--info' else 't-Badge--success' end SEV_CSS, round(f.pct, 1) USED_PCT, f.days_to_full DTF
from c_fit f where f.kind = 'TBSPC' and ((:P0_DB is null or f.db = :P0_DB) and (:P0_TARGET is null or f.db in (select t.db_pdb from c_cont t where t.target_name = :P0_TARGET)))
order by f.days_to_full nulls last, f.pct desc nulls last fetch first 10 rows only~', false);
    check_query(q'~p1 Tablespace used % / Critical~', q'~with c_cont as (select c001 db_pdb, c002 db_name, c003 con_name, c004 target_name, n001 dbid, n002 con_dbid from awrcap_probe_coll where collection_name = 'AWRCAP_CONTAINER'),
c_fit as (select c001 db, c002 kind, c003 series, c004 unit, c005 method, c006 quality, c007 sev, c008 limit_source, d001 last_day, n001 value, n002 limit_value, n003 pct, n004 days_to_full, n005 sev_rank, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') slope_per_day, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') r2, to_number(c011, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') days_to_full_lo, to_number(c012, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') days_to_full_hi, to_number(c013, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') accel, to_number(c014, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') train_n from awrcap_probe_coll where collection_name = 'AWRCAP_FIT')
select case when :P0_DB is null then f.db || ' ' || f.series else f.series end label, round(f.pct, 1) value from c_fit f where f.kind = 'TBSPC' and f.sev = 'CRIT' and ((:P0_DB is null or f.db = :P0_DB) and (:P0_TARGET is null or f.db in (select t.db_pdb from c_cont t where t.target_name = :P0_TARGET))) order by f.pct desc~', false);
    check_query(q'~p1 Tablespace used % / Warning~', q'~with c_cont as (select c001 db_pdb, c002 db_name, c003 con_name, c004 target_name, n001 dbid, n002 con_dbid from awrcap_probe_coll where collection_name = 'AWRCAP_CONTAINER'),
c_fit as (select c001 db, c002 kind, c003 series, c004 unit, c005 method, c006 quality, c007 sev, c008 limit_source, d001 last_day, n001 value, n002 limit_value, n003 pct, n004 days_to_full, n005 sev_rank, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') slope_per_day, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') r2, to_number(c011, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') days_to_full_lo, to_number(c012, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') days_to_full_hi, to_number(c013, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') accel, to_number(c014, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') train_n from awrcap_probe_coll where collection_name = 'AWRCAP_FIT')
select case when :P0_DB is null then f.db || ' ' || f.series else f.series end label, round(f.pct, 1) value from c_fit f where f.kind = 'TBSPC' and f.sev = 'WARN' and ((:P0_DB is null or f.db = :P0_DB) and (:P0_TARGET is null or f.db in (select t.db_pdb from c_cont t where t.target_name = :P0_TARGET))) order by f.pct desc~', false);
    check_query(q'~p1 Tablespace used % / OK~', q'~with c_cont as (select c001 db_pdb, c002 db_name, c003 con_name, c004 target_name, n001 dbid, n002 con_dbid from awrcap_probe_coll where collection_name = 'AWRCAP_CONTAINER'),
c_fit as (select c001 db, c002 kind, c003 series, c004 unit, c005 method, c006 quality, c007 sev, c008 limit_source, d001 last_day, n001 value, n002 limit_value, n003 pct, n004 days_to_full, n005 sev_rank, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') slope_per_day, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') r2, to_number(c011, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') days_to_full_lo, to_number(c012, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') days_to_full_hi, to_number(c013, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') accel, to_number(c014, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') train_n from awrcap_probe_coll where collection_name = 'AWRCAP_FIT')
select case when :P0_DB is null then f.db || ' ' || f.series else f.series end label, round(f.pct, 1) value from c_fit f where f.kind = 'TBSPC' and f.sev not in ('CRIT', 'WARN') and ((:P0_DB is null or f.db = :P0_DB) and (:P0_TARGET is null or f.db in (select t.db_pdb from c_cont t where t.target_name = :P0_TARGET))) order by f.pct desc~', false);
  end check_page_1;
  procedure check_page_5(p_demo in boolean) is
  begin
    check_query(q'~p0 Data~', q'~with c_cont as (select c001 db_pdb, c002 db_name, c003 con_name, c004 target_name, n001 dbid, n002 con_dbid from awrcap_probe_coll where collection_name = 'AWRCAP_CONTAINER'),
c_series as (select c001 db, c002 kind, c003 series, c004 unit, c005 anomaly_flag, d001 ts, n001 value, n002 limit_value, n003 expected, n004 rate_bpd, n005 anomaly, to_number(c006, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') pct, to_number(c007, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') gap, to_number(c008, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') z, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') threshold, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') delta_bytes, to_number(c011, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') busy_p95, to_number(c012, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') busy_peak_pct from awrcap_probe_coll where collection_name = 'AWRCAP_SERIES'),
c_meta as (select n001 cpu_sat_pct, n002 dtf_warn, n003 dtf_crit, n004 nearfull_warn_pct, n005 nearfull_crit_pct, to_number(c001, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') series_sat_pct, to_number(c002, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') anomaly_report_days, d001 loaded_at from awrcap_probe_coll where collection_name = 'AWRCAP_META')
select (select count(distinct s.db) from c_series s where ((:P0_DB is null or s.db = :P0_DB) and (:P0_TARGET is null or s.db in (select t.db_pdb from c_cont t where t.target_name = :P0_TARGET)))) DATABASES, (select to_char(max(s.ts), 'YYYY-MM-DD') from c_series s where ((:P0_DB is null or s.db = :P0_DB) and (:P0_TARGET is null or s.db in (select t.db_pdb from c_cont t where t.target_name = :P0_TARGET)))) LATEST, (select to_char(min(l.ts), 'YYYY-MM-DD') from (select max(s.ts) ts from c_series s where ((:P0_DB is null or s.db = :P0_DB) and (:P0_TARGET is null or s.db in (select t.db_pdb from c_cont t where t.target_name = :P0_TARGET))) group by s.db) l) STALEST, (select to_char(m.loaded_at, 'HH24:MI') from c_meta m) LOADED
from dual~', p_demo);
    check_query(q'~p5 Fleet summary~', q'~with c_cont as (select c001 db_pdb, c002 db_name, c003 con_name, c004 target_name, n001 dbid, n002 con_dbid from awrcap_probe_coll where collection_name = 'AWRCAP_CONTAINER'),
c_tgt as (select c001 target_name, c002 db_name, c003 feed, c004 host_name, c005 db_link, c006 enabled, c007 is_stale, c008 collect_state, c009 last_error, d001 newest_snap, d002 last_ok_at, d003 last_error_at, n001 dbid, n002 n_containers, n003 age_hours, n004 n_gaps, n005 collected_snap_id from awrcap_probe_coll where collection_name = 'AWRCAP_TARGETS'),
c_alert as (select c001 severity, c002 kind, c003 db_pdb, c004 series_key, c005 unit, c006 message, d001 day_dt, n001 sev_rank, n002 value, n003 threshold from awrcap_probe_coll where collection_name = 'AWRCAP_ALERTS')
select (select count(distinct t.target_name) from c_tgt t) TARGETS, (select count(*) from c_cont c) CONTAINERS, (select count(*) from c_tgt t where t.is_stale = 'Y') STALE, (select count(*) from c_tgt t where t.collect_state in ('FAILING', 'NEVER')) FAILING, (select count(*) from c_alert a where a.severity = 'CRIT') CRIT
from dual~', false);
    check_query(q'~p5 Targets~', q'~with c_cont as (select c001 db_pdb, c002 db_name, c003 con_name, c004 target_name, n001 dbid, n002 con_dbid from awrcap_probe_coll where collection_name = 'AWRCAP_CONTAINER'),
c_tgt as (select c001 target_name, c002 db_name, c003 feed, c004 host_name, c005 db_link, c006 enabled, c007 is_stale, c008 collect_state, c009 last_error, d001 newest_snap, d002 last_ok_at, d003 last_error_at, n001 dbid, n002 n_containers, n003 age_hours, n004 n_gaps, n005 collected_snap_id from awrcap_probe_coll where collection_name = 'AWRCAP_TARGETS'),
c_fit as (select c001 db, c002 kind, c003 series, c004 unit, c005 method, c006 quality, c007 sev, c008 limit_source, d001 last_day, n001 value, n002 limit_value, n003 pct, n004 days_to_full, n005 sev_rank, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') slope_per_day, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') r2, to_number(c011, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') days_to_full_lo, to_number(c012, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') days_to_full_hi, to_number(c013, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') accel, to_number(c014, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') train_n from awrcap_probe_coll where collection_name = 'AWRCAP_FIT'),
c_alert as (select c001 severity, c002 kind, c003 db_pdb, c004 series_key, c005 unit, c006 message, d001 day_dt, n001 sev_rank, n002 value, n003 threshold from awrcap_probe_coll where collection_name = 'AWRCAP_ALERTS')
select t.target_name TARGET, ('f?p=' || (1) || ':P0_TARGET,P0_DB,P0_TBSPC:' || t.target_name || ',,') TARGET_URL, to_char(t.dbid) DBID, t.db_name DB_NAME, t.host_name HOST_NAME, t.feed FEED, t.n_containers CONTAINERS, to_char(t.newest_snap, 'YYYY-MM-DD HH24:MI') NEWEST_SNAP, round(t.age_hours, 1) AGE_HOURS, case t.is_stale when 'Y' then 'STALE' when 'N' then 'FRESH' end FRESHNESS, case t.is_stale when 'Y' then 't-Badge--warning' when 'N' then 't-Badge--success' end FRESHNESS_CSS, t.collect_state COLLECT_STATE, case t.collect_state when 'FAILING' then 't-Badge--danger' when 'NEVER' then 't-Badge--warning' when 'DISABLED' then 't-Badge--info' when 'OK' then 't-Badge--success' end COLLECT_STATE_CSS, (select count(*) from c_alert a where a.severity = 'CRIT' and a.db_pdb in (select c.db_pdb from c_cont c where c.dbid = t.dbid)) CRIT, (select count(*) from c_alert a where a.severity = 'WARN' and a.db_pdb in (select c.db_pdb from c_cont c where c.dbid = t.dbid)) WARN, (select min(f.days_to_full) from c_fit f where f.kind = 'TBSPC' and f.db in (select c.db_pdb from c_cont c where c.dbid = t.dbid)) DTF, to_char(t.last_ok_at, 'YYYY-MM-DD HH24:MI') LAST_OK, to_char(t.last_error_at, 'YYYY-MM-DD HH24:MI') LAST_ERROR_AT, t.last_error LAST_ERROR, t.n_gaps GAPS, t.db_link DB_LINK, t.enabled ENABLED
from c_tgt t~', p_demo);
    check_query(q'~p5 Hours since the newest snapshot / Stale~', q'~with c_tgt as (select c001 target_name, c002 db_name, c003 feed, c004 host_name, c005 db_link, c006 enabled, c007 is_stale, c008 collect_state, c009 last_error, d001 newest_snap, d002 last_ok_at, d003 last_error_at, n001 dbid, n002 n_containers, n003 age_hours, n004 n_gaps, n005 collected_snap_id from awrcap_probe_coll where collection_name = 'AWRCAP_TARGETS')
select t.target_name || case when t.db_name <> t.target_name then ' ' || t.db_name end label, round(t.age_hours, 1) value from c_tgt t where t.is_stale = 'Y' order by t.age_hours desc~', false);
    check_query(q'~p5 Hours since the newest snapshot / Fresh~', q'~with c_tgt as (select c001 target_name, c002 db_name, c003 feed, c004 host_name, c005 db_link, c006 enabled, c007 is_stale, c008 collect_state, c009 last_error, d001 newest_snap, d002 last_ok_at, d003 last_error_at, n001 dbid, n002 n_containers, n003 age_hours, n004 n_gaps, n005 collected_snap_id from awrcap_probe_coll where collection_name = 'AWRCAP_TARGETS')
select t.target_name || case when t.db_name <> t.target_name then ' ' || t.db_name end label, round(t.age_hours, 1) value from c_tgt t where t.is_stale = 'N' order by t.age_hours desc~', false);
  end check_page_5;
  procedure check_page_2(p_demo in boolean) is
  begin
    check_query(q'~p0 P0_TARGET lov~', q'~with c_cont as (select c001 db_pdb, c002 db_name, c003 con_name, c004 target_name, n001 dbid, n002 con_dbid from awrcap_probe_coll where collection_name = 'AWRCAP_CONTAINER')
select c.target_name d, c.target_name r from c_cont c where c.target_name is not null group by c.target_name order by 1~', false);
    check_query(q'~p0 P0_DB lov~', q'~with c_cont as (select c001 db_pdb, c002 db_name, c003 con_name, c004 target_name, n001 dbid, n002 con_dbid from awrcap_probe_coll where collection_name = 'AWRCAP_CONTAINER')
select c.db_pdb d, c.db_pdb r from c_cont c where (:P0_TARGET is null or c.target_name = :P0_TARGET) group by c.db_pdb order by 1~', false);
    check_query(q'~p0 P0_TBSPC lov~', q'~with c_cont as (select c001 db_pdb, c002 db_name, c003 con_name, c004 target_name, n001 dbid, n002 con_dbid from awrcap_probe_coll where collection_name = 'AWRCAP_CONTAINER'),
c_fit as (select c001 db, c002 kind, c003 series, c004 unit, c005 method, c006 quality, c007 sev, c008 limit_source, d001 last_day, n001 value, n002 limit_value, n003 pct, n004 days_to_full, n005 sev_rank, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') slope_per_day, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') r2, to_number(c011, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') days_to_full_lo, to_number(c012, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') days_to_full_hi, to_number(c013, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') accel, to_number(c014, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') train_n from awrcap_probe_coll where collection_name = 'AWRCAP_FIT')
select f.series || case when :P0_DB is null then ' (' || f.db || ')' end d, f.db || '|' || f.series r from c_fit f where f.kind = 'TBSPC' and ((:P0_DB is null or f.db = :P0_DB) and (:P0_TARGET is null or f.db in (select t.db_pdb from c_cont t where t.target_name = :P0_TARGET))) order by 1~', false);
    check_query(q'~p0 Data~', q'~with c_cont as (select c001 db_pdb, c002 db_name, c003 con_name, c004 target_name, n001 dbid, n002 con_dbid from awrcap_probe_coll where collection_name = 'AWRCAP_CONTAINER'),
c_series as (select c001 db, c002 kind, c003 series, c004 unit, c005 anomaly_flag, d001 ts, n001 value, n002 limit_value, n003 expected, n004 rate_bpd, n005 anomaly, to_number(c006, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') pct, to_number(c007, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') gap, to_number(c008, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') z, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') threshold, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') delta_bytes, to_number(c011, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') busy_p95, to_number(c012, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') busy_peak_pct from awrcap_probe_coll where collection_name = 'AWRCAP_SERIES'),
c_meta as (select n001 cpu_sat_pct, n002 dtf_warn, n003 dtf_crit, n004 nearfull_warn_pct, n005 nearfull_crit_pct, to_number(c001, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') series_sat_pct, to_number(c002, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') anomaly_report_days, d001 loaded_at from awrcap_probe_coll where collection_name = 'AWRCAP_META')
select (select count(distinct s.db) from c_series s where ((:P0_DB is null or s.db = :P0_DB) and (:P0_TARGET is null or s.db in (select t.db_pdb from c_cont t where t.target_name = :P0_TARGET)))) DATABASES, (select to_char(max(s.ts), 'YYYY-MM-DD') from c_series s where ((:P0_DB is null or s.db = :P0_DB) and (:P0_TARGET is null or s.db in (select t.db_pdb from c_cont t where t.target_name = :P0_TARGET)))) LATEST, (select to_char(min(l.ts), 'YYYY-MM-DD') from (select max(s.ts) ts from c_series s where ((:P0_DB is null or s.db = :P0_DB) and (:P0_TARGET is null or s.db in (select t.db_pdb from c_cont t where t.target_name = :P0_TARGET))) group by s.db) l) STALEST, (select to_char(m.loaded_at, 'HH24:MI') from c_meta m) LOADED
from dual~', p_demo);
    check_query(q'~p2 Tablespace summary~', q'~with c_cont as (select c001 db_pdb, c002 db_name, c003 con_name, c004 target_name, n001 dbid, n002 con_dbid from awrcap_probe_coll where collection_name = 'AWRCAP_CONTAINER'),
c_fit as (select c001 db, c002 kind, c003 series, c004 unit, c005 method, c006 quality, c007 sev, c008 limit_source, d001 last_day, n001 value, n002 limit_value, n003 pct, n004 days_to_full, n005 sev_rank, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') slope_per_day, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') r2, to_number(c011, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') days_to_full_lo, to_number(c012, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') days_to_full_hi, to_number(c013, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') accel, to_number(c014, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') train_n from awrcap_probe_coll where collection_name = 'AWRCAP_FIT'),
c_anom as (select c001 db, c002 kind, c003 series, c004 anomaly_kind, c005 anomaly_flag, c006 unit, c007 sev, c008 message, d001 ts, d002 obs_day, n001 value, n002 expected, n003 threshold, n004 z, n005 sev_rank, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') shift_pct, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') rate_bpd from awrcap_probe_coll where collection_name = 'AWRCAP_ANOMALIES')
select (select count(*) from c_fit f where f.kind = 'TBSPC' and f.sev = 'CRIT' and ((:P0_DB is null or f.db = :P0_DB) and (:P0_TARGET is null or f.db in (select t.db_pdb from c_cont t where t.target_name = :P0_TARGET)))) CRIT, (select count(*) from c_fit f where f.kind = 'TBSPC' and f.sev = 'WARN' and ((:P0_DB is null or f.db = :P0_DB) and (:P0_TARGET is null or f.db in (select t.db_pdb from c_cont t where t.target_name = :P0_TARGET)))) WARN, (select count(*) from c_anom a where a.kind = 'TBSPC' and ((:P0_DB is null or a.db = :P0_DB) and (:P0_TARGET is null or a.db in (select t.db_pdb from c_cont t where t.target_name = :P0_TARGET))) and a.ts between nvl(to_date(:P0_FROM default null on conversion error, 'YYYY-MM-DD'), a.ts) and nvl(to_date(:P0_TO default null on conversion error, 'YYYY-MM-DD'), a.ts)) ANOM, (select nvl(to_char(min(f.days_to_full)), '-') from c_fit f where f.kind = 'TBSPC' and ((:P0_DB is null or f.db = :P0_DB) and (:P0_TARGET is null or f.db in (select t.db_pdb from c_cont t where t.target_name = :P0_TARGET)))) DTF
from dual~', false);
    check_query(q'~p2 Days to full~', q'~with c_cont as (select c001 db_pdb, c002 db_name, c003 con_name, c004 target_name, n001 dbid, n002 con_dbid from awrcap_probe_coll where collection_name = 'AWRCAP_CONTAINER'),
c_fit as (select c001 db, c002 kind, c003 series, c004 unit, c005 method, c006 quality, c007 sev, c008 limit_source, d001 last_day, n001 value, n002 limit_value, n003 pct, n004 days_to_full, n005 sev_rank, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') slope_per_day, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') r2, to_number(c011, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') days_to_full_lo, to_number(c012, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') days_to_full_hi, to_number(c013, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') accel, to_number(c014, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') train_n from awrcap_probe_coll where collection_name = 'AWRCAP_FIT')
select (select max(t.target_name) from c_cont t where t.db_pdb = f.db) TARGET, f.db DB, f.series TABLESPACE, ('f?p=' || (2) || ':P0_TBSPC:' || f.db || '|' || f.series) TABLESPACE_URL, f.sev SEV, case f.sev when 'CRIT' then 't-Badge--danger' when 'WARN' then 't-Badge--warning' when 'INFO' then 't-Badge--info' else 't-Badge--success' end SEV_CSS, round(f.pct, 1) USED_PCT, round(f.value / 1073741824, 2) USED_GIB, round(f.limit_value / 1073741824, 2) CEILING_GIB, round(f.slope_per_day / 1048576, 1) GROWTH_MIB, f.days_to_full DTF, f.days_to_full_lo DTF_LO, f.days_to_full_hi DTF_HI, round(f.r2, 3) R2, f.quality QUALITY, f.limit_source LIMIT_SOURCE
from c_fit f where f.kind = 'TBSPC' and ((:P0_DB is null or f.db = :P0_DB) and (:P0_TARGET is null or f.db in (select t.db_pdb from c_cont t where t.target_name = :P0_TARGET)))~', false);
    check_query(q'~p2 Used space / Used~', q'~with c_cont as (select c001 db_pdb, c002 db_name, c003 con_name, c004 target_name, n001 dbid, n002 con_dbid from awrcap_probe_coll where collection_name = 'AWRCAP_CONTAINER'),
c_series as (select c001 db, c002 kind, c003 series, c004 unit, c005 anomaly_flag, d001 ts, n001 value, n002 limit_value, n003 expected, n004 rate_bpd, n005 anomaly, to_number(c006, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') pct, to_number(c007, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') gap, to_number(c008, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') z, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') threshold, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') delta_bytes, to_number(c011, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') busy_p95, to_number(c012, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') busy_peak_pct from awrcap_probe_coll where collection_name = 'AWRCAP_SERIES')
select s.ts, round(s.value / 1073741824, 2) value, case when :P0_TBSPC = 'ALL' then case when :P0_DB is null then s.db || ' ' || s.series else s.series end else 'Used GiB' end name from c_series s where s.kind = 'TBSPC' and (s.db || '|' || s.series = :P0_TBSPC or (:P0_TBSPC = 'ALL' and ((:P0_DB is null or s.db = :P0_DB) and (:P0_TARGET is null or s.db in (select t.db_pdb from c_cont t where t.target_name = :P0_TARGET))))) and s.ts between nvl(to_date(:P0_FROM default null on conversion error, 'YYYY-MM-DD'), s.ts) and nvl(to_date(:P0_TO default null on conversion error, 'YYYY-MM-DD'), s.ts) order by s.ts~', p_demo);
    check_query(q'~p2 Used space / Forecast~', q'~with c_fcst as (select c001 db, c002 kind, c003 series, c004 unit, c005 method, c006 quality, d001 ts, n001 value, n002 lo, n003 hi, n004 limit_value, n005 horizon_days, to_number(c007, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') pct from awrcap_probe_coll where collection_name = 'AWRCAP_FORECAST')
select f.ts, round(f.value / 1073741824, 2) value from c_fcst f where f.kind = 'TBSPC' and f.method = 'REGR' and f.db || '|' || f.series = :P0_TBSPC and f.ts between nvl(to_date(:P0_FROM default null on conversion error, 'YYYY-MM-DD'), f.ts) and nvl(to_date(:P0_TO default null on conversion error, 'YYYY-MM-DD'), f.ts) order by f.ts~', false);
    check_query(q'~p2 Used space / Forecast low~', q'~with c_fcst as (select c001 db, c002 kind, c003 series, c004 unit, c005 method, c006 quality, d001 ts, n001 value, n002 lo, n003 hi, n004 limit_value, n005 horizon_days, to_number(c007, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') pct from awrcap_probe_coll where collection_name = 'AWRCAP_FORECAST')
select f.ts, round(nvl(f.lo, f.value) / 1073741824, 2) value from c_fcst f where f.kind = 'TBSPC' and f.method = 'REGR' and f.db || '|' || f.series = :P0_TBSPC and f.ts between nvl(to_date(:P0_FROM default null on conversion error, 'YYYY-MM-DD'), f.ts) and nvl(to_date(:P0_TO default null on conversion error, 'YYYY-MM-DD'), f.ts) order by f.ts~', false);
    check_query(q'~p2 Used space / Forecast high~', q'~with c_fcst as (select c001 db, c002 kind, c003 series, c004 unit, c005 method, c006 quality, d001 ts, n001 value, n002 lo, n003 hi, n004 limit_value, n005 horizon_days, to_number(c007, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') pct from awrcap_probe_coll where collection_name = 'AWRCAP_FORECAST')
select f.ts, round(nvl(f.hi, f.value) / 1073741824, 2) value from c_fcst f where f.kind = 'TBSPC' and f.method = 'REGR' and f.db || '|' || f.series = :P0_TBSPC and f.ts between nvl(to_date(:P0_FROM default null on conversion error, 'YYYY-MM-DD'), f.ts) and nvl(to_date(:P0_TO default null on conversion error, 'YYYY-MM-DD'), f.ts) order by f.ts~', false);
    check_query(q'~p2 Used space / Ceiling~', q'~with c_fit as (select c001 db, c002 kind, c003 series, c004 unit, c005 method, c006 quality, c007 sev, c008 limit_source, d001 last_day, n001 value, n002 limit_value, n003 pct, n004 days_to_full, n005 sev_rank, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') slope_per_day, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') r2, to_number(c011, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') days_to_full_lo, to_number(c012, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') days_to_full_hi, to_number(c013, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') accel, to_number(c014, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') train_n from awrcap_probe_coll where collection_name = 'AWRCAP_FIT')
select e.ts, l.value from (select round(f.limit_value / 1073741824, 2) value from c_fit f where f.kind = 'TBSPC' and f.db || '|' || f.series = :P0_TBSPC) l cross join (select to_date(:P0_FROM default null on conversion error, 'YYYY-MM-DD') ts from dual union all select to_date(:P0_TO default null on conversion error, 'YYYY-MM-DD') ts from dual) e where e.ts is not null and l.value is not null order by e.ts~', false);
    check_query(q'~p2 Used space / ESM +30~', q'~with c_fcst as (select c001 db, c002 kind, c003 series, c004 unit, c005 method, c006 quality, d001 ts, n001 value, n002 lo, n003 hi, n004 limit_value, n005 horizon_days, to_number(c007, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') pct from awrcap_probe_coll where collection_name = 'AWRCAP_FORECAST')
select f.ts, round(f.value / 1073741824, 2) value from c_fcst f where f.kind = 'TBSPC' and f.method = 'ESM' and f.db || '|' || f.series = :P0_TBSPC and f.ts between nvl(to_date(:P0_FROM default null on conversion error, 'YYYY-MM-DD'), f.ts) and nvl(to_date(:P0_TO default null on conversion error, 'YYYY-MM-DD'), f.ts)~', false);
    check_query(q'~p2 Used space / Anomaly~', q'~with c_cont as (select c001 db_pdb, c002 db_name, c003 con_name, c004 target_name, n001 dbid, n002 con_dbid from awrcap_probe_coll where collection_name = 'AWRCAP_CONTAINER'),
c_series as (select c001 db, c002 kind, c003 series, c004 unit, c005 anomaly_flag, d001 ts, n001 value, n002 limit_value, n003 expected, n004 rate_bpd, n005 anomaly, to_number(c006, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') pct, to_number(c007, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') gap, to_number(c008, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') z, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') threshold, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') delta_bytes, to_number(c011, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') busy_p95, to_number(c012, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') busy_peak_pct from awrcap_probe_coll where collection_name = 'AWRCAP_SERIES')
select s.ts, round(s.value / 1073741824, 2) value from c_series s where s.kind = 'TBSPC' and s.anomaly = 1 and (s.db || '|' || s.series = :P0_TBSPC or (:P0_TBSPC = 'ALL' and ((:P0_DB is null or s.db = :P0_DB) and (:P0_TARGET is null or s.db in (select t.db_pdb from c_cont t where t.target_name = :P0_TARGET))))) and s.ts between nvl(to_date(:P0_FROM default null on conversion error, 'YYYY-MM-DD'), s.ts) and nvl(to_date(:P0_TO default null on conversion error, 'YYYY-MM-DD'), s.ts) order by s.ts~', false);
    check_query(q'~p2 Daily growth / Growth~', q'~with c_series as (select c001 db, c002 kind, c003 series, c004 unit, c005 anomaly_flag, d001 ts, n001 value, n002 limit_value, n003 expected, n004 rate_bpd, n005 anomaly, to_number(c006, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') pct, to_number(c007, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') gap, to_number(c008, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') z, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') threshold, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') delta_bytes, to_number(c011, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') busy_p95, to_number(c012, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') busy_peak_pct from awrcap_probe_coll where collection_name = 'AWRCAP_SERIES')
select s.ts, round(s.rate_bpd / 1048576, 1) value from c_series s where s.kind = 'TBSPC' and s.db || '|' || s.series = :P0_TBSPC and nvl(s.anomaly, 0) = 0 and s.ts between nvl(to_date(:P0_FROM default null on conversion error, 'YYYY-MM-DD'), s.ts) and nvl(to_date(:P0_TO default null on conversion error, 'YYYY-MM-DD'), s.ts) order by s.ts~', false);
    check_query(q'~p2 Daily growth / Anomalous growth~', q'~with c_series as (select c001 db, c002 kind, c003 series, c004 unit, c005 anomaly_flag, d001 ts, n001 value, n002 limit_value, n003 expected, n004 rate_bpd, n005 anomaly, to_number(c006, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') pct, to_number(c007, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') gap, to_number(c008, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') z, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') threshold, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') delta_bytes, to_number(c011, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') busy_p95, to_number(c012, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') busy_peak_pct from awrcap_probe_coll where collection_name = 'AWRCAP_SERIES')
select s.ts, round(s.rate_bpd / 1048576, 1) value from c_series s where s.kind = 'TBSPC' and s.db || '|' || s.series = :P0_TBSPC and s.anomaly = 1 and s.ts between nvl(to_date(:P0_FROM default null on conversion error, 'YYYY-MM-DD'), s.ts) and nvl(to_date(:P0_TO default null on conversion error, 'YYYY-MM-DD'), s.ts) order by s.ts~', false);
    check_query(q'~p2 Daily growth / Median rate~', q'~with c_series as (select c001 db, c002 kind, c003 series, c004 unit, c005 anomaly_flag, d001 ts, n001 value, n002 limit_value, n003 expected, n004 rate_bpd, n005 anomaly, to_number(c006, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') pct, to_number(c007, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') gap, to_number(c008, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') z, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') threshold, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') delta_bytes, to_number(c011, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') busy_p95, to_number(c012, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') busy_peak_pct from awrcap_probe_coll where collection_name = 'AWRCAP_SERIES')
select s.ts, round(s.expected / 1048576, 1) value from c_series s where s.kind = 'TBSPC' and s.db || '|' || s.series = :P0_TBSPC and s.ts between nvl(to_date(:P0_FROM default null on conversion error, 'YYYY-MM-DD'), s.ts) and nvl(to_date(:P0_TO default null on conversion error, 'YYYY-MM-DD'), s.ts) order by s.ts~', false);
    check_query(q'~p2 Growth anomalies~', q'~with c_cont as (select c001 db_pdb, c002 db_name, c003 con_name, c004 target_name, n001 dbid, n002 con_dbid from awrcap_probe_coll where collection_name = 'AWRCAP_CONTAINER'),
c_anom as (select c001 db, c002 kind, c003 series, c004 anomaly_kind, c005 anomaly_flag, c006 unit, c007 sev, c008 message, d001 ts, d002 obs_day, n001 value, n002 expected, n003 threshold, n004 z, n005 sev_rank, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') shift_pct, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') rate_bpd from awrcap_probe_coll where collection_name = 'AWRCAP_ANOMALIES')
select a.ts DAY, (select max(t.target_name) from c_cont t where t.db_pdb = a.db) TARGET, a.db DB, a.series TABLESPACE, ('f?p=' || (2) || ':P0_TBSPC:' || a.db || '|' || a.series) TABLESPACE_URL, a.anomaly_kind ANOMALY_KIND, a.sev SEV, case a.sev when 'CRIT' then 't-Badge--danger' when 'WARN' then 't-Badge--warning' when 'INFO' then 't-Badge--info' else 't-Badge--success' end SEV_CSS, round(a.value / 1073741824, 2) GROWTH_GIB, round(a.rate_bpd / 1048576, 1) RATE_MIB, round(a.expected / 1048576, 1) MEDIAN_MIB, round(a.threshold / 1048576, 1) THRESHOLD_MIB, round(a.z, 1) Z, a.anomaly_flag FLAG, a.message MESSAGE
from c_anom a where a.kind = 'TBSPC' and ((:P0_DB is null or a.db = :P0_DB) and (:P0_TARGET is null or a.db in (select t.db_pdb from c_cont t where t.target_name = :P0_TARGET))) and a.ts between nvl(to_date(:P0_FROM default null on conversion error, 'YYYY-MM-DD'), a.ts) and nvl(to_date(:P0_TO default null on conversion error, 'YYYY-MM-DD'), a.ts)~', false);
    check_query(q'~p2 Tablespace alerts~', q'~with c_cont as (select c001 db_pdb, c002 db_name, c003 con_name, c004 target_name, n001 dbid, n002 con_dbid from awrcap_probe_coll where collection_name = 'AWRCAP_CONTAINER'),
c_alert as (select c001 severity, c002 kind, c003 db_pdb, c004 series_key, c005 unit, c006 message, d001 day_dt, n001 sev_rank, n002 value, n003 threshold from awrcap_probe_coll where collection_name = 'AWRCAP_ALERTS')
select a.severity SEV, case a.severity when 'CRIT' then 't-Badge--danger' when 'WARN' then 't-Badge--warning' when 'INFO' then 't-Badge--info' else 't-Badge--success' end SEV_CSS, a.sev_rank SEV_RANK, a.kind KIND, (select max(t.target_name) from c_cont t where t.db_pdb = a.db_pdb) TARGET, a.db_pdb DB, a.series_key SERIES, a.day_dt DAY, round(a.value, 2) VALUE, round(a.threshold, 2) THRESHOLD, case lower(a.unit) when 'io_per_sec' then 'requests/s' when 'mb_per_sec' then 'MB/s' else a.unit end UNIT, a.message MESSAGE
from c_alert a where a.kind like 'TBSPC%' and ((:P0_DB is null or a.db_pdb = :P0_DB) and (:P0_TARGET is null or a.db_pdb in (select t.db_pdb from c_cont t where t.target_name = :P0_TARGET)))
order by a.sev_rank, a.day_dt desc~', false);
  end check_page_2;
  procedure check_page_3(p_demo in boolean) is
  begin
    check_query(q'~p0 P0_TARGET lov~', q'~with c_cont as (select c001 db_pdb, c002 db_name, c003 con_name, c004 target_name, n001 dbid, n002 con_dbid from awrcap_probe_coll where collection_name = 'AWRCAP_CONTAINER')
select c.target_name d, c.target_name r from c_cont c where c.target_name is not null group by c.target_name order by 1~', false);
    check_query(q'~p0 P0_DB lov~', q'~with c_cont as (select c001 db_pdb, c002 db_name, c003 con_name, c004 target_name, n001 dbid, n002 con_dbid from awrcap_probe_coll where collection_name = 'AWRCAP_CONTAINER')
select c.db_pdb d, c.db_pdb r from c_cont c where (:P0_TARGET is null or c.target_name = :P0_TARGET) group by c.db_pdb order by 1~', false);
    check_query(q'~p0 Data~', q'~with c_cont as (select c001 db_pdb, c002 db_name, c003 con_name, c004 target_name, n001 dbid, n002 con_dbid from awrcap_probe_coll where collection_name = 'AWRCAP_CONTAINER'),
c_series as (select c001 db, c002 kind, c003 series, c004 unit, c005 anomaly_flag, d001 ts, n001 value, n002 limit_value, n003 expected, n004 rate_bpd, n005 anomaly, to_number(c006, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') pct, to_number(c007, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') gap, to_number(c008, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') z, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') threshold, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') delta_bytes, to_number(c011, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') busy_p95, to_number(c012, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') busy_peak_pct from awrcap_probe_coll where collection_name = 'AWRCAP_SERIES'),
c_meta as (select n001 cpu_sat_pct, n002 dtf_warn, n003 dtf_crit, n004 nearfull_warn_pct, n005 nearfull_crit_pct, to_number(c001, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') series_sat_pct, to_number(c002, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') anomaly_report_days, d001 loaded_at from awrcap_probe_coll where collection_name = 'AWRCAP_META')
select (select count(distinct s.db) from c_series s where ((:P0_DB is null or s.db = :P0_DB) and (:P0_TARGET is null or s.db in (select t.db_pdb from c_cont t where t.target_name = :P0_TARGET)))) DATABASES, (select to_char(max(s.ts), 'YYYY-MM-DD') from c_series s where ((:P0_DB is null or s.db = :P0_DB) and (:P0_TARGET is null or s.db in (select t.db_pdb from c_cont t where t.target_name = :P0_TARGET)))) LATEST, (select to_char(min(l.ts), 'YYYY-MM-DD') from (select max(s.ts) ts from c_series s where ((:P0_DB is null or s.db = :P0_DB) and (:P0_TARGET is null or s.db in (select t.db_pdb from c_cont t where t.target_name = :P0_TARGET))) group by s.db) l) STALEST, (select to_char(m.loaded_at, 'HH24:MI') from c_meta m) LOADED
from dual~', p_demo);
    check_query(q'~p3 Host CPU busy % / Busy %~', q'~with c_cont as (select c001 db_pdb, c002 db_name, c003 con_name, c004 target_name, n001 dbid, n002 con_dbid from awrcap_probe_coll where collection_name = 'AWRCAP_CONTAINER'),
c_series as (select c001 db, c002 kind, c003 series, c004 unit, c005 anomaly_flag, d001 ts, n001 value, n002 limit_value, n003 expected, n004 rate_bpd, n005 anomaly, to_number(c006, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') pct, to_number(c007, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') gap, to_number(c008, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') z, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') threshold, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') delta_bytes, to_number(c011, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') busy_p95, to_number(c012, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') busy_peak_pct from awrcap_probe_coll where collection_name = 'AWRCAP_SERIES')
select s.ts, round(s.value, 1) value, s.db || ' busy %' name from c_series s where s.kind = 'CPU' and s.series = 'BUSY_PCT' and ((:P0_DB is null or s.db in (select r.db_pdb from c_cont r, c_cont c where c.db_pdb = :P0_DB and r.dbid = c.dbid and r.con_dbid = r.dbid)) and (:P0_TARGET is null or s.db in (select t.db_pdb from c_cont t where t.target_name = :P0_TARGET))) and s.ts between nvl(to_date(:P0_FROM default null on conversion error, 'YYYY-MM-DD'), s.ts) and nvl(to_date(:P0_TO default null on conversion error, 'YYYY-MM-DD'), s.ts) order by s.ts~', p_demo);
    check_query(q'~p3 Host CPU busy % / Busy-hour p95~', q'~with c_cont as (select c001 db_pdb, c002 db_name, c003 con_name, c004 target_name, n001 dbid, n002 con_dbid from awrcap_probe_coll where collection_name = 'AWRCAP_CONTAINER'),
c_series as (select c001 db, c002 kind, c003 series, c004 unit, c005 anomaly_flag, d001 ts, n001 value, n002 limit_value, n003 expected, n004 rate_bpd, n005 anomaly, to_number(c006, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') pct, to_number(c007, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') gap, to_number(c008, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') z, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') threshold, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') delta_bytes, to_number(c011, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') busy_p95, to_number(c012, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') busy_peak_pct from awrcap_probe_coll where collection_name = 'AWRCAP_SERIES')
select s.ts, round(s.busy_p95, 1) value, s.db || ' busy-hour p95' name from c_series s where s.kind = 'CPU' and s.series = 'BUSY_PCT' and ((:P0_DB is null or s.db in (select r.db_pdb from c_cont r, c_cont c where c.db_pdb = :P0_DB and r.dbid = c.dbid and r.con_dbid = r.dbid)) and (:P0_TARGET is null or s.db in (select t.db_pdb from c_cont t where t.target_name = :P0_TARGET))) and s.ts between nvl(to_date(:P0_FROM default null on conversion error, 'YYYY-MM-DD'), s.ts) and nvl(to_date(:P0_TO default null on conversion error, 'YYYY-MM-DD'), s.ts) order by s.ts~', false);
    check_query(q'~p3 Host CPU busy % / Forecast~', q'~with c_cont as (select c001 db_pdb, c002 db_name, c003 con_name, c004 target_name, n001 dbid, n002 con_dbid from awrcap_probe_coll where collection_name = 'AWRCAP_CONTAINER'),
c_fcst as (select c001 db, c002 kind, c003 series, c004 unit, c005 method, c006 quality, d001 ts, n001 value, n002 lo, n003 hi, n004 limit_value, n005 horizon_days, to_number(c007, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') pct from awrcap_probe_coll where collection_name = 'AWRCAP_FORECAST')
select f.ts, round(f.value, 2) value, f.db || ' forecast' name from c_fcst f where f.kind = 'CPU' and f.method = 'REGR' and f.series = 'BUSY_P95' and ((:P0_DB is null or f.db in (select r.db_pdb from c_cont r, c_cont c where c.db_pdb = :P0_DB and r.dbid = c.dbid and r.con_dbid = r.dbid)) and (:P0_TARGET is null or f.db in (select t.db_pdb from c_cont t where t.target_name = :P0_TARGET))) and f.ts between nvl(to_date(:P0_FROM default null on conversion error, 'YYYY-MM-DD'), f.ts) and nvl(to_date(:P0_TO default null on conversion error, 'YYYY-MM-DD'), f.ts) order by f.ts~', false);
    check_query(q'~p3 Host CPU busy % / Forecast low~', q'~with c_cont as (select c001 db_pdb, c002 db_name, c003 con_name, c004 target_name, n001 dbid, n002 con_dbid from awrcap_probe_coll where collection_name = 'AWRCAP_CONTAINER'),
c_fcst as (select c001 db, c002 kind, c003 series, c004 unit, c005 method, c006 quality, d001 ts, n001 value, n002 lo, n003 hi, n004 limit_value, n005 horizon_days, to_number(c007, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') pct from awrcap_probe_coll where collection_name = 'AWRCAP_FORECAST')
select f.ts, round(nvl(f.lo, f.value), 2) value, f.db || ' forecast low' name from c_fcst f where f.kind = 'CPU' and f.method = 'REGR' and f.series = 'BUSY_P95' and ((:P0_DB is null or f.db in (select r.db_pdb from c_cont r, c_cont c where c.db_pdb = :P0_DB and r.dbid = c.dbid and r.con_dbid = r.dbid)) and (:P0_TARGET is null or f.db in (select t.db_pdb from c_cont t where t.target_name = :P0_TARGET))) and f.ts between nvl(to_date(:P0_FROM default null on conversion error, 'YYYY-MM-DD'), f.ts) and nvl(to_date(:P0_TO default null on conversion error, 'YYYY-MM-DD'), f.ts) order by f.ts~', false);
    check_query(q'~p3 Host CPU busy % / Forecast high~', q'~with c_cont as (select c001 db_pdb, c002 db_name, c003 con_name, c004 target_name, n001 dbid, n002 con_dbid from awrcap_probe_coll where collection_name = 'AWRCAP_CONTAINER'),
c_fcst as (select c001 db, c002 kind, c003 series, c004 unit, c005 method, c006 quality, d001 ts, n001 value, n002 lo, n003 hi, n004 limit_value, n005 horizon_days, to_number(c007, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') pct from awrcap_probe_coll where collection_name = 'AWRCAP_FORECAST')
select f.ts, round(nvl(f.hi, f.value), 2) value, f.db || ' forecast high' name from c_fcst f where f.kind = 'CPU' and f.method = 'REGR' and f.series = 'BUSY_P95' and ((:P0_DB is null or f.db in (select r.db_pdb from c_cont r, c_cont c where c.db_pdb = :P0_DB and r.dbid = c.dbid and r.con_dbid = r.dbid)) and (:P0_TARGET is null or f.db in (select t.db_pdb from c_cont t where t.target_name = :P0_TARGET))) and f.ts between nvl(to_date(:P0_FROM default null on conversion error, 'YYYY-MM-DD'), f.ts) and nvl(to_date(:P0_TO default null on conversion error, 'YYYY-MM-DD'), f.ts) order by f.ts~', false);
    check_query(q'~p3 Host CPU busy % / Saturation~', q'~with c_meta as (select n001 cpu_sat_pct, n002 dtf_warn, n003 dtf_crit, n004 nearfull_warn_pct, n005 nearfull_crit_pct, to_number(c001, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') series_sat_pct, to_number(c002, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') anomaly_report_days, d001 loaded_at from awrcap_probe_coll where collection_name = 'AWRCAP_META')
select e.ts, l.value from (select m.cpu_sat_pct value from c_meta m) l cross join (select to_date(:P0_FROM default null on conversion error, 'YYYY-MM-DD') ts from dual union all select to_date(:P0_TO default null on conversion error, 'YYYY-MM-DD') ts from dual) e where e.ts is not null and l.value is not null order by e.ts~', false);
    check_query(q'~p3 Host CPU busy % / Anomaly~', q'~with c_cont as (select c001 db_pdb, c002 db_name, c003 con_name, c004 target_name, n001 dbid, n002 con_dbid from awrcap_probe_coll where collection_name = 'AWRCAP_CONTAINER'),
c_series as (select c001 db, c002 kind, c003 series, c004 unit, c005 anomaly_flag, d001 ts, n001 value, n002 limit_value, n003 expected, n004 rate_bpd, n005 anomaly, to_number(c006, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') pct, to_number(c007, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') gap, to_number(c008, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') z, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') threshold, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') delta_bytes, to_number(c011, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') busy_p95, to_number(c012, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') busy_peak_pct from awrcap_probe_coll where collection_name = 'AWRCAP_SERIES')
select s.ts, round(s.value, 1) value from c_series s where s.kind = 'CPU' and s.series = 'BUSY_PCT' and s.anomaly = 1 and ((:P0_DB is null or s.db in (select r.db_pdb from c_cont r, c_cont c where c.db_pdb = :P0_DB and r.dbid = c.dbid and r.con_dbid = r.dbid)) and (:P0_TARGET is null or s.db in (select t.db_pdb from c_cont t where t.target_name = :P0_TARGET))) and s.ts between nvl(to_date(:P0_FROM default null on conversion error, 'YYYY-MM-DD'), s.ts) and nvl(to_date(:P0_TO default null on conversion error, 'YYYY-MM-DD'), s.ts) order by s.ts~', false);
    check_query(q'~p3 DB CPU % of host per container / DB CPU %~', q'~with c_cont as (select c001 db_pdb, c002 db_name, c003 con_name, c004 target_name, n001 dbid, n002 con_dbid from awrcap_probe_coll where collection_name = 'AWRCAP_CONTAINER'),
c_series as (select c001 db, c002 kind, c003 series, c004 unit, c005 anomaly_flag, d001 ts, n001 value, n002 limit_value, n003 expected, n004 rate_bpd, n005 anomaly, to_number(c006, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') pct, to_number(c007, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') gap, to_number(c008, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') z, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') threshold, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') delta_bytes, to_number(c011, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') busy_p95, to_number(c012, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') busy_peak_pct from awrcap_probe_coll where collection_name = 'AWRCAP_SERIES')
select s.ts, round(s.value, 1) value, s.db name from c_series s where s.kind = 'CPU' and s.series = 'DB_CPU_PCT' and ((:P0_DB is null or s.db = :P0_DB) and (:P0_TARGET is null or s.db in (select t.db_pdb from c_cont t where t.target_name = :P0_TARGET))) and s.ts between nvl(to_date(:P0_FROM default null on conversion error, 'YYYY-MM-DD'), s.ts) and nvl(to_date(:P0_TO default null on conversion error, 'YYYY-MM-DD'), s.ts) order by s.ts~', false);
    check_query(q'~p3 DB CPU % of host per container / Level shift~', q'~with c_cont as (select c001 db_pdb, c002 db_name, c003 con_name, c004 target_name, n001 dbid, n002 con_dbid from awrcap_probe_coll where collection_name = 'AWRCAP_CONTAINER'),
c_anom as (select c001 db, c002 kind, c003 series, c004 anomaly_kind, c005 anomaly_flag, c006 unit, c007 sev, c008 message, d001 ts, d002 obs_day, n001 value, n002 expected, n003 threshold, n004 z, n005 sev_rank, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') shift_pct, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') rate_bpd from awrcap_probe_coll where collection_name = 'AWRCAP_ANOMALIES')
select case k.n when 1 then a.ts else a.obs_day end ts, round(a.value, 1) value, 'Level shift ' || a.db || ' from ' || to_char(a.ts, 'YYYY-MM-DD') name from c_anom a cross join (select 1 n from dual union all select 2 n from dual) k where a.anomaly_kind = 'CPU_SHIFT' and ((:P0_DB is null or a.db = :P0_DB) and (:P0_TARGET is null or a.db in (select t.db_pdb from c_cont t where t.target_name = :P0_TARGET))) and a.obs_day between nvl(to_date(:P0_FROM default null on conversion error, 'YYYY-MM-DD'), a.obs_day) and nvl(to_date(:P0_TO default null on conversion error, 'YYYY-MM-DD'), a.obs_day) order by 3, 1~', false);
    check_query(q'~p3 CPU trend~', q'~with c_cont as (select c001 db_pdb, c002 db_name, c003 con_name, c004 target_name, n001 dbid, n002 con_dbid from awrcap_probe_coll where collection_name = 'AWRCAP_CONTAINER'),
