select (select max(t.target_name) from c_cont t where t.db_pdb = f.db) TARGET, f.db DB, f.series METRIC, f.sev SEV, case f.sev when 'CRIT' then 't-Badge--danger' when 'WARN' then 't-Badge--warning' when 'INFO' then 't-Badge--info' else 't-Badge--success' end SEV_CSS, round(f.value, 1) CURRENT_VALUE, case lower(f.unit) when 'io_per_sec' then 'requests/s' when 'mb_per_sec' then 'MB/s' else f.unit end UNIT, round(f.slope_per_day, 3) SLOPE, f.days_to_full DTS, f.days_to_full_lo DTS_LO, f.days_to_full_hi DTS_HI, round(f.r2, 3) R2, f.quality QUALITY
from c_fit f where f.kind = 'CPU' and (f.series in ('BUSY_PCT', 'BUSY_P95', 'BUSY_PEAK') and ((:P0_DB is null or f.db in (select r.db_pdb from c_cont r, c_cont c where c.db_pdb = :P0_DB and r.dbid = c.dbid and r.con_dbid = r.dbid)) and (:P0_TARGET is null or f.db in (select t.db_pdb from c_cont t where t.target_name = :P0_TARGET))) or f.series not in ('BUSY_PCT', 'BUSY_P95', 'BUSY_PEAK') and ((:P0_DB is null or f.db = :P0_DB) and (:P0_TARGET is null or f.db in (select t.db_pdb from c_cont t where t.target_name = :P0_TARGET))))~', false);
