c_fit as (select c001 db, c002 kind, c003 series, c004 unit, c005 method, c006 quality, c007 sev, c008 limit_source, d001 last_day, n001 value, n002 limit_value, n003 pct, n004 days_to_full, n005 sev_rank, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') slope_per_day, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') r2, to_number(c011, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') days_to_full_lo, to_number(c012, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') days_to_full_hi, to_number(c013, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') accel, to_number(c014, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') train_n from awrcap_probe_coll where collection_name = 'AWRCAP_FIT')
select (select max(t.target_name) from c_cont t where t.db_pdb = f.db) TARGET, f.db DB, f.series SERIES, f.sev SEV, case f.sev when 'CRIT' then 't-Badge--danger' when 'WARN' then 't-Badge--warning' when 'INFO' then 't-Badge--info' else 't-Badge--success' end SEV_CSS, round(f.value, 2) CURRENT_VALUE, case lower(f.unit) when 'io_per_sec' then 'requests/s' when 'mb_per_sec' then 'MB/s' else f.unit end UNIT, round(f.limit_value, 2) LIMIT_VALUE, round(f.pct, 1) PCT, f.days_to_full DTL, round(f.slope_per_day, 3) SLOPE, round(f.r2, 3) R2, f.quality QUALITY
from c_fit f where f.kind = 'SERIES' and ((:P0_DB is null or f.db = :P0_DB) and (:P0_TARGET is null or f.db in (select t.db_pdb from c_cont t where t.target_name = :P0_TARGET)))~', false);
    check_query(q'~p3 CPU and series alerts~', q'~with c_cont as (select c001 db_pdb, c002 db_name, c003 con_name, c004 target_name, n001 dbid, n002 con_dbid from awrcap_probe_coll where collection_name = 'AWRCAP_CONTAINER'),
c_alert as (select c001 severity, c002 kind, c003 db_pdb, c004 series_key, c005 unit, c006 message, d001 day_dt, n001 sev_rank, n002 value, n003 threshold from awrcap_probe_coll where collection_name = 'AWRCAP_ALERTS')
select a.severity SEV, case a.severity when 'CRIT' then 't-Badge--danger' when 'WARN' then 't-Badge--warning' when 'INFO' then 't-Badge--info' else 't-Badge--success' end SEV_CSS, a.sev_rank SEV_RANK, a.kind KIND, (select max(t.target_name) from c_cont t where t.db_pdb = a.db_pdb) TARGET, a.db_pdb DB, a.series_key SERIES, a.day_dt DAY, round(a.value, 2) VALUE, round(a.threshold, 2) THRESHOLD, case lower(a.unit) when 'io_per_sec' then 'requests/s' when 'mb_per_sec' then 'MB/s' else a.unit end UNIT, a.message MESSAGE
from c_alert a where a.kind not like 'TBSPC%' and (((:P0_DB is null or a.db_pdb = :P0_DB) and (:P0_TARGET is null or a.db_pdb in (select t.db_pdb from c_cont t where t.target_name = :P0_TARGET))) or ((:P0_DB is null or a.db_pdb in (select r.db_pdb from c_cont r, c_cont c where c.db_pdb = :P0_DB and r.dbid = c.dbid and r.con_dbid = r.dbid)) and (:P0_TARGET is null or a.db_pdb in (select t.db_pdb from c_cont t where t.target_name = :P0_TARGET))))
order by a.sev_rank, a.day_dt desc~', false);
  end check_page_3;
  procedure check_page_6(p_demo in boolean) is
  begin
    check_query(q'~p0 P0_TARGET lov~', q'~with c_cont as (select c001 db_pdb, c002 db_name, c003 con_name, c004 target_name, n001 dbid, n002 con_dbid from awrcap_probe_coll where collection_name = 'AWRCAP_CONTAINER')
select c.target_name d, c.target_name r from c_cont c where c.target_name is not null group by c.target_name order by 1~', false);
    check_query(q'~p0 P0_DB lov~', q'~with c_cont as (select c001 db_pdb, c002 db_name, c003 con_name, c004 target_name, n001 dbid, n002 con_dbid from awrcap_probe_coll where collection_name = 'AWRCAP_CONTAINER')
select c.db_pdb d, c.db_pdb r from c_cont c where (:P0_TARGET is null or c.target_name = :P0_TARGET) group by c.db_pdb order by 1~', false);
    check_query(q'~p0 Data~', q'~with c_cont as (select c001 db_pdb, c002 db_name, c003 con_name, c004 target_name, n001 dbid, n002 con_dbid from awrcap_probe_coll where collection_name = 'AWRCAP_CONTAINER'),
c_series as (select c001 db, c002 kind, c003 series, c004 unit, c005 anomaly_flag, d001 ts, n001 value, n002 limit_value, n003 expected, n004 rate_bpd, n005 anomaly, to_number(c006, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') pct, to_number(c007, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') gap, to_number(c008, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') z, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') threshold, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') delta_bytes, to_number(c011, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') busy_p95, to_number(c012, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') busy_peak_pct from awrcap_probe_coll where collection_name = 'AWRCAP_SERIES'),
c_meta as (select n001 cpu_sat_pct, n002 dtf_warn, n003 dtf_crit, n004 nearfull_warn_pct, n005 nearfull_crit_pct, to_number(c001, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') series_sat_pct, to_number(c002, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') anomaly_report_days, d001 loaded_at from awrcap_probe_coll where collection_name = 'AWRCAP_META')
select (select count(distinct s.db) from c_series s where ((:P0_DB is null or s.db = :P0_DB) and (:P0_TARGET is null or s.db in (select t.db_pdb from c_cont t where t.target_name = :P0_TARGET)))) DATABASES, (select to_char(max(s.ts), 'YYYY-MM-DD') from c_series s where ((:P0_DB is null or s.db = :P0_DB) and (:P0_TARGET is null or s.db in (select t.db_pdb from c_cont t where t.target_name = :P0_TARGET)))) LATEST, (select to_char(min(l.ts), 'YYYY-MM-DD') from (select max(s.ts) ts from c_series s where ((:P0_DB is null or s.db = :P0_DB) and (:P0_TARGET is null or s.db in (select t.db_pdb from c_cont t where t.target_name = :P0_TARGET))) group by s.db) l) STALEST, (select to_char(m.loaded_at, 'HH24:MI') from c_meta m) LOADED
from dual~', p_demo);
    check_query(q'~p6 Memory summary~', q'~with c_cont as (select c001 db_pdb, c002 db_name, c003 con_name, c004 target_name, n001 dbid, n002 con_dbid from awrcap_probe_coll where collection_name = 'AWRCAP_CONTAINER'),
c_memv as (select c001 db_pdb, c002 area, c003 area_label, c004 mem_mode, c005 grade, c006 reason, c007 reason_text, c008 actionable, c009 current_size, c010 suggested_size, c011 suggested_param, c012 exceeds_host_ram, c013 exceeds_sga, c014 headline, d001 window_start, d002 window_end, n001 instance_number, n002 area_rank, n003 current_bytes, n004 suggested_bytes, n005 change_pct, to_number(c015, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') n_evidence, to_number(c016, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') n_pressure, to_number(c017, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') n_days, to_number(c018, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') rank_mem from awrcap_probe_coll where collection_name = 'AWRCAP_MEM_VERDICT'),
c_meme as (select c001 db_pdb, c002 area, c003 area_label, c004 kind, c005 signal, c006 direction, c007 unit, c008 evidence_text, d001 observed_at, n001 instance_number, n002 area_rank, n003 value, n004 threshold, n005 rank_ev from awrcap_probe_coll where collection_name = 'AWRCAP_MEM_EVIDENCE')
select (select count(*) from c_memv m where ((:P0_DB is null or m.db_pdb in (select r.db_pdb from c_cont r, c_cont c where c.db_pdb = :P0_DB and r.dbid = c.dbid and r.con_dbid = r.dbid)) and (:P0_TARGET is null or m.db_pdb in (select t.db_pdb from c_cont t where t.target_name = :P0_TARGET)))) AREAS, (select count(*) from c_memv m where m.actionable = 'Y' and ((:P0_DB is null or m.db_pdb in (select r.db_pdb from c_cont r, c_cont c where c.db_pdb = :P0_DB and r.dbid = c.dbid and r.con_dbid = r.dbid)) and (:P0_TARGET is null or m.db_pdb in (select t.db_pdb from c_cont t where t.target_name = :P0_TARGET)))) ACTIONABLE, (select count(*) from c_memv m where m.grade = 'UNDERSIZED' and ((:P0_DB is null or m.db_pdb in (select r.db_pdb from c_cont r, c_cont c where c.db_pdb = :P0_DB and r.dbid = c.dbid and r.con_dbid = r.dbid)) and (:P0_TARGET is null or m.db_pdb in (select t.db_pdb from c_cont t where t.target_name = :P0_TARGET)))) UNDERSIZED, (select count(*) from c_memv m where m.grade = 'OVERSIZED' and ((:P0_DB is null or m.db_pdb in (select r.db_pdb from c_cont r, c_cont c where c.db_pdb = :P0_DB and r.dbid = c.dbid and r.con_dbid = r.dbid)) and (:P0_TARGET is null or m.db_pdb in (select t.db_pdb from c_cont t where t.target_name = :P0_TARGET)))) OVERSIZED, (select count(*) from c_meme e where e.direction = 'PRESSURE' and ((:P0_DB is null or e.db_pdb in (select r.db_pdb from c_cont r, c_cont c where c.db_pdb = :P0_DB and r.dbid = c.dbid and r.con_dbid = r.dbid)) and (:P0_TARGET is null or e.db_pdb in (select t.db_pdb from c_cont t where t.target_name = :P0_TARGET)))) PRESSURE
from dual~', false);
    check_query(q'~p6 Memory verdicts~', q'~with c_cont as (select c001 db_pdb, c002 db_name, c003 con_name, c004 target_name, n001 dbid, n002 con_dbid from awrcap_probe_coll where collection_name = 'AWRCAP_CONTAINER'),
c_memv as (select c001 db_pdb, c002 area, c003 area_label, c004 mem_mode, c005 grade, c006 reason, c007 reason_text, c008 actionable, c009 current_size, c010 suggested_size, c011 suggested_param, c012 exceeds_host_ram, c013 exceeds_sga, c014 headline, d001 window_start, d002 window_end, n001 instance_number, n002 area_rank, n003 current_bytes, n004 suggested_bytes, n005 change_pct, to_number(c015, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') n_evidence, to_number(c016, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') n_pressure, to_number(c017, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') n_days, to_number(c018, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') rank_mem from awrcap_probe_coll where collection_name = 'AWRCAP_MEM_VERDICT')
select (select max(t.target_name) from c_cont t where t.db_pdb = m.db_pdb) TARGET, m.db_pdb DB, m.instance_number INST, m.area_label AREA, m.grade GRADE, case m.grade when 'UNDERSIZED' then 't-Badge--warning' when 'THRASHING' then 't-Badge--warning' when 'OVERSIZED' then 't-Badge--info' when 'DRIFTING' then 't-Badge--info' when 'OK' then 't-Badge--success' end GRADE_CSS, m.current_size CURRENT_SIZE, m.suggested_size SUGGESTED_SIZE, m.change_pct CHANGE_PCT, m.suggested_param PARAM, m.headline HEADLINE, m.reason_text REASON, trim(case when m.exceeds_host_ram = 'Y' then 'exceeds host RAM ' end || case when m.exceeds_sga = 'Y' then 'exceeds sga_target' end) FLAGS, m.mem_mode MEM_MODE, m.n_evidence SIGNALS, m.n_pressure PRESSURE, m.n_days DAYS_SAMPLED, m.window_start WINDOW_START, m.window_end WINDOW_END, m.rank_mem RANK_MEM
from c_memv m where ((:P0_DB is null or m.db_pdb in (select r.db_pdb from c_cont r, c_cont c where c.db_pdb = :P0_DB and r.dbid = c.dbid and r.con_dbid = r.dbid)) and (:P0_TARGET is null or m.db_pdb in (select t.db_pdb from c_cont t where t.target_name = :P0_TARGET)))~', p_demo);
    check_query(q'~p6 SGA components / Component~', q'~with c_cont as (select c001 db_pdb, c002 db_name, c003 con_name, c004 target_name, n001 dbid, n002 con_dbid from awrcap_probe_coll where collection_name = 'AWRCAP_CONTAINER'),
c_memp as (select c001 db_pdb, c002 component, d001 ts, n001 instance_number, n002 bytes, n003 min_bytes, n004 max_bytes, n005 ops from awrcap_probe_coll where collection_name = 'AWRCAP_MEM_POINTS')
select p.ts, round(p.bytes / 1073741824, 2) value, case when :P0_DB is null then p.db_pdb || ' ' || p.component else p.component end || case when p.instance_number > 1 then ' #' || p.instance_number end name from c_memp p where ((:P0_DB is null or p.db_pdb in (select r.db_pdb from c_cont r, c_cont c where c.db_pdb = :P0_DB and r.dbid = c.dbid and r.con_dbid = r.dbid)) and (:P0_TARGET is null or p.db_pdb in (select t.db_pdb from c_cont t where t.target_name = :P0_TARGET))) and p.ts between nvl(to_date(:P0_FROM default null on conversion error, 'YYYY-MM-DD'), p.ts) and nvl(to_date(:P0_TO default null on conversion error, 'YYYY-MM-DD'), p.ts) order by p.ts~', p_demo);
    check_query(q'~p6 PGA allocated (GiB) / Observed~', q'~with c_cont as (select c001 db_pdb, c002 db_name, c003 con_name, c004 target_name, n001 dbid, n002 con_dbid from awrcap_probe_coll where collection_name = 'AWRCAP_CONTAINER'),
c_series as (select c001 db, c002 kind, c003 series, c004 unit, c005 anomaly_flag, d001 ts, n001 value, n002 limit_value, n003 expected, n004 rate_bpd, n005 anomaly, to_number(c006, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') pct, to_number(c007, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') gap, to_number(c008, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') z, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') threshold, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') delta_bytes, to_number(c011, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') busy_p95, to_number(c012, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') busy_peak_pct from awrcap_probe_coll where collection_name = 'AWRCAP_SERIES')
select s.ts, round(s.value, 2) value, s.db name from c_series s where s.kind = 'SERIES' and s.series = 'PGA_ALLOC_GB' and ((:P0_DB is null or s.db in (select r.db_pdb from c_cont r, c_cont c where c.db_pdb = :P0_DB and r.dbid = c.dbid and r.con_dbid = r.dbid)) and (:P0_TARGET is null or s.db in (select t.db_pdb from c_cont t where t.target_name = :P0_TARGET))) and s.ts between nvl(to_date(:P0_FROM default null on conversion error, 'YYYY-MM-DD'), s.ts) and nvl(to_date(:P0_TO default null on conversion error, 'YYYY-MM-DD'), s.ts) order by s.ts~', false);
    check_query(q'~p6 PGA allocated (GiB) / Forecast~', q'~with c_cont as (select c001 db_pdb, c002 db_name, c003 con_name, c004 target_name, n001 dbid, n002 con_dbid from awrcap_probe_coll where collection_name = 'AWRCAP_CONTAINER'),
c_fcst as (select c001 db, c002 kind, c003 series, c004 unit, c005 method, c006 quality, d001 ts, n001 value, n002 lo, n003 hi, n004 limit_value, n005 horizon_days, to_number(c007, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') pct from awrcap_probe_coll where collection_name = 'AWRCAP_FORECAST')
select f.ts, round(f.value, 2) value, f.db || ' forecast' name from c_fcst f where f.kind = 'SERIES' and f.method = 'REGR' and f.series = 'PGA_ALLOC_GB' and ((:P0_DB is null or f.db in (select r.db_pdb from c_cont r, c_cont c where c.db_pdb = :P0_DB and r.dbid = c.dbid and r.con_dbid = r.dbid)) and (:P0_TARGET is null or f.db in (select t.db_pdb from c_cont t where t.target_name = :P0_TARGET))) and f.ts between nvl(to_date(:P0_FROM default null on conversion error, 'YYYY-MM-DD'), f.ts) and nvl(to_date(:P0_TO default null on conversion error, 'YYYY-MM-DD'), f.ts) order by f.ts~', false);
    check_query(q'~p6 PGA allocated (GiB) / Forecast low~', q'~with c_cont as (select c001 db_pdb, c002 db_name, c003 con_name, c004 target_name, n001 dbid, n002 con_dbid from awrcap_probe_coll where collection_name = 'AWRCAP_CONTAINER'),
c_fcst as (select c001 db, c002 kind, c003 series, c004 unit, c005 method, c006 quality, d001 ts, n001 value, n002 lo, n003 hi, n004 limit_value, n005 horizon_days, to_number(c007, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') pct from awrcap_probe_coll where collection_name = 'AWRCAP_FORECAST')
select f.ts, round(nvl(f.lo, f.value), 2) value, f.db || ' forecast low' name from c_fcst f where f.kind = 'SERIES' and f.method = 'REGR' and f.series = 'PGA_ALLOC_GB' and ((:P0_DB is null or f.db in (select r.db_pdb from c_cont r, c_cont c where c.db_pdb = :P0_DB and r.dbid = c.dbid and r.con_dbid = r.dbid)) and (:P0_TARGET is null or f.db in (select t.db_pdb from c_cont t where t.target_name = :P0_TARGET))) and f.ts between nvl(to_date(:P0_FROM default null on conversion error, 'YYYY-MM-DD'), f.ts) and nvl(to_date(:P0_TO default null on conversion error, 'YYYY-MM-DD'), f.ts) order by f.ts~', false);
    check_query(q'~p6 PGA allocated (GiB) / Forecast high~', q'~with c_cont as (select c001 db_pdb, c002 db_name, c003 con_name, c004 target_name, n001 dbid, n002 con_dbid from awrcap_probe_coll where collection_name = 'AWRCAP_CONTAINER'),
c_fcst as (select c001 db, c002 kind, c003 series, c004 unit, c005 method, c006 quality, d001 ts, n001 value, n002 lo, n003 hi, n004 limit_value, n005 horizon_days, to_number(c007, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') pct from awrcap_probe_coll where collection_name = 'AWRCAP_FORECAST')
select f.ts, round(nvl(f.hi, f.value), 2) value, f.db || ' forecast high' name from c_fcst f where f.kind = 'SERIES' and f.method = 'REGR' and f.series = 'PGA_ALLOC_GB' and ((:P0_DB is null or f.db in (select r.db_pdb from c_cont r, c_cont c where c.db_pdb = :P0_DB and r.dbid = c.dbid and r.con_dbid = r.dbid)) and (:P0_TARGET is null or f.db in (select t.db_pdb from c_cont t where t.target_name = :P0_TARGET))) and f.ts between nvl(to_date(:P0_FROM default null on conversion error, 'YYYY-MM-DD'), f.ts) and nvl(to_date(:P0_TO default null on conversion error, 'YYYY-MM-DD'), f.ts) order by f.ts~', false);
    check_query(q'~p6 PGA allocated (GiB) / Limit~', q'~with c_cont as (select c001 db_pdb, c002 db_name, c003 con_name, c004 target_name, n001 dbid, n002 con_dbid from awrcap_probe_coll where collection_name = 'AWRCAP_CONTAINER'),
c_fit as (select c001 db, c002 kind, c003 series, c004 unit, c005 method, c006 quality, c007 sev, c008 limit_source, d001 last_day, n001 value, n002 limit_value, n003 pct, n004 days_to_full, n005 sev_rank, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') slope_per_day, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') r2, to_number(c011, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') days_to_full_lo, to_number(c012, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') days_to_full_hi, to_number(c013, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') accel, to_number(c014, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') train_n from awrcap_probe_coll where collection_name = 'AWRCAP_FIT')
select e.ts, l.value, l.db || ' limit' name from (select f.limit_value value, f.db from c_fit f where f.kind = 'SERIES' and f.series = 'PGA_ALLOC_GB' and ((:P0_DB is null or f.db in (select r.db_pdb from c_cont r, c_cont c where c.db_pdb = :P0_DB and r.dbid = c.dbid and r.con_dbid = r.dbid)) and (:P0_TARGET is null or f.db in (select t.db_pdb from c_cont t where t.target_name = :P0_TARGET)))) l cross join (select to_date(:P0_FROM default null on conversion error, 'YYYY-MM-DD') ts from dual union all select to_date(:P0_TO default null on conversion error, 'YYYY-MM-DD') ts from dual) e where e.ts is not null and l.value is not null order by e.ts~', false);
    check_query(q'~p6 Memory evidence~', q'~with c_cont as (select c001 db_pdb, c002 db_name, c003 con_name, c004 target_name, n001 dbid, n002 con_dbid from awrcap_probe_coll where collection_name = 'AWRCAP_CONTAINER'),
c_meme as (select c001 db_pdb, c002 area, c003 area_label, c004 kind, c005 signal, c006 direction, c007 unit, c008 evidence_text, d001 observed_at, n001 instance_number, n002 area_rank, n003 value, n004 threshold, n005 rank_ev from awrcap_probe_coll where collection_name = 'AWRCAP_MEM_EVIDENCE')
select (select max(t.target_name) from c_cont t where t.db_pdb = e.db_pdb) TARGET, e.db_pdb DB, e.instance_number INST, e.area_label AREA, e.kind KIND, e.signal SIGNAL, e.direction DIRECTION, case e.direction when 'PRESSURE' then 't-Badge--warning' when 'SLACK' then 't-Badge--info' end DIRECTION_CSS, round(e.value, 2) VALUE, e.unit UNIT, round(e.threshold, 2) THRESHOLD, to_char(e.observed_at, 'YYYY-MM-DD HH24:MI') OBSERVED, e.evidence_text EVIDENCE, e.rank_ev RANK_EV
from c_meme e where ((:P0_DB is null or e.db_pdb in (select r.db_pdb from c_cont r, c_cont c where c.db_pdb = :P0_DB and r.dbid = c.dbid and r.con_dbid = r.dbid)) and (:P0_TARGET is null or e.db_pdb in (select t.db_pdb from c_cont t where t.target_name = :P0_TARGET)))~', false);
  end check_page_6;
  procedure check_page_4(p_demo in boolean) is
  begin
    check_query(q'~p0 P0_TARGET lov~', q'~with c_cont as (select c001 db_pdb, c002 db_name, c003 con_name, c004 target_name, n001 dbid, n002 con_dbid from awrcap_probe_coll where collection_name = 'AWRCAP_CONTAINER')
select c.target_name d, c.target_name r from c_cont c where c.target_name is not null group by c.target_name order by 1~', false);
    check_query(q'~p0 P0_DB lov~', q'~with c_cont as (select c001 db_pdb, c002 db_name, c003 con_name, c004 target_name, n001 dbid, n002 con_dbid from awrcap_probe_coll where collection_name = 'AWRCAP_CONTAINER')
select c.db_pdb d, c.db_pdb r from c_cont c where (:P0_TARGET is null or c.target_name = :P0_TARGET) group by c.db_pdb order by 1~', false);
    check_query(q'~p0 P0_KIND lov~', q'~with c_anom as (select c001 db, c002 kind, c003 series, c004 anomaly_kind, c005 anomaly_flag, c006 unit, c007 sev, c008 message, d001 ts, d002 obs_day, n001 value, n002 expected, n003 threshold, n004 z, n005 sev_rank, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') shift_pct, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') rate_bpd from awrcap_probe_coll where collection_name = 'AWRCAP_ANOMALIES')
select a.anomaly_kind d, a.anomaly_kind r from c_anom a group by a.anomaly_kind order by 1~', false);
    check_query(q'~p0 P0_SEV lov~', q'~with c_anom as (select c001 db, c002 kind, c003 series, c004 anomaly_kind, c005 anomaly_flag, c006 unit, c007 sev, c008 message, d001 ts, d002 obs_day, n001 value, n002 expected, n003 threshold, n004 z, n005 sev_rank, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') shift_pct, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') rate_bpd from awrcap_probe_coll where collection_name = 'AWRCAP_ANOMALIES')
select a.sev d, a.sev r from c_anom a group by a.sev order by min(a.sev_rank)~', false);
    check_query(q'~p0 Data~', q'~with c_cont as (select c001 db_pdb, c002 db_name, c003 con_name, c004 target_name, n001 dbid, n002 con_dbid from awrcap_probe_coll where collection_name = 'AWRCAP_CONTAINER'),
c_series as (select c001 db, c002 kind, c003 series, c004 unit, c005 anomaly_flag, d001 ts, n001 value, n002 limit_value, n003 expected, n004 rate_bpd, n005 anomaly, to_number(c006, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') pct, to_number(c007, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') gap, to_number(c008, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') z, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') threshold, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') delta_bytes, to_number(c011, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') busy_p95, to_number(c012, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') busy_peak_pct from awrcap_probe_coll where collection_name = 'AWRCAP_SERIES'),
c_meta as (select n001 cpu_sat_pct, n002 dtf_warn, n003 dtf_crit, n004 nearfull_warn_pct, n005 nearfull_crit_pct, to_number(c001, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') series_sat_pct, to_number(c002, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') anomaly_report_days, d001 loaded_at from awrcap_probe_coll where collection_name = 'AWRCAP_META')
select (select count(distinct s.db) from c_series s where ((:P0_DB is null or s.db = :P0_DB) and (:P0_TARGET is null or s.db in (select t.db_pdb from c_cont t where t.target_name = :P0_TARGET)))) DATABASES, (select to_char(max(s.ts), 'YYYY-MM-DD') from c_series s where ((:P0_DB is null or s.db = :P0_DB) and (:P0_TARGET is null or s.db in (select t.db_pdb from c_cont t where t.target_name = :P0_TARGET)))) LATEST, (select to_char(min(l.ts), 'YYYY-MM-DD') from (select max(s.ts) ts from c_series s where ((:P0_DB is null or s.db = :P0_DB) and (:P0_TARGET is null or s.db in (select t.db_pdb from c_cont t where t.target_name = :P0_TARGET))) group by s.db) l) STALEST, (select to_char(m.loaded_at, 'HH24:MI') from c_meta m) LOADED
from dual~', p_demo);
    check_query(q'~p4 Anomaly summary~', q'~with c_cont as (select c001 db_pdb, c002 db_name, c003 con_name, c004 target_name, n001 dbid, n002 con_dbid from awrcap_probe_coll where collection_name = 'AWRCAP_CONTAINER'),
c_anom as (select c001 db, c002 kind, c003 series, c004 anomaly_kind, c005 anomaly_flag, c006 unit, c007 sev, c008 message, d001 ts, d002 obs_day, n001 value, n002 expected, n003 threshold, n004 z, n005 sev_rank, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') shift_pct, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') rate_bpd from awrcap_probe_coll where collection_name = 'AWRCAP_ANOMALIES')
select (select count(*) from c_anom a where ((:P0_DB is null or a.db = :P0_DB) and (:P0_TARGET is null or a.db in (select t.db_pdb from c_cont t where t.target_name = :P0_TARGET))) and a.ts between nvl(to_date(:P0_FROM default null on conversion error, 'YYYY-MM-DD'), a.ts) and nvl(to_date(:P0_TO default null on conversion error, 'YYYY-MM-DD'), a.ts) and (:P0_KIND is null or a.anomaly_kind = :P0_KIND) and (:P0_SEV is null or a.sev = :P0_SEV)) ANOMALIES, (select count(distinct a.db) from c_anom a where ((:P0_DB is null or a.db = :P0_DB) and (:P0_TARGET is null or a.db in (select t.db_pdb from c_cont t where t.target_name = :P0_TARGET))) and a.ts between nvl(to_date(:P0_FROM default null on conversion error, 'YYYY-MM-DD'), a.ts) and nvl(to_date(:P0_TO default null on conversion error, 'YYYY-MM-DD'), a.ts) and (:P0_KIND is null or a.anomaly_kind = :P0_KIND) and (:P0_SEV is null or a.sev = :P0_SEV)) DATABASES, (select count(distinct a.db || '|' || a.series) from c_anom a where ((:P0_DB is null or a.db = :P0_DB) and (:P0_TARGET is null or a.db in (select t.db_pdb from c_cont t where t.target_name = :P0_TARGET))) and a.ts between nvl(to_date(:P0_FROM default null on conversion error, 'YYYY-MM-DD'), a.ts) and nvl(to_date(:P0_TO default null on conversion error, 'YYYY-MM-DD'), a.ts) and (:P0_KIND is null or a.anomaly_kind = :P0_KIND) and (:P0_SEV is null or a.sev = :P0_SEV)) SERIES, (select count(*) from c_anom a where a.sev in ('WARN', 'CRIT') and ((:P0_DB is null or a.db = :P0_DB) and (:P0_TARGET is null or a.db in (select t.db_pdb from c_cont t where t.target_name = :P0_TARGET))) and a.ts between nvl(to_date(:P0_FROM default null on conversion error, 'YYYY-MM-DD'), a.ts) and nvl(to_date(:P0_TO default null on conversion error, 'YYYY-MM-DD'), a.ts) and (:P0_KIND is null or a.anomaly_kind = :P0_KIND) and (:P0_SEV is null or a.sev = :P0_SEV)) SERIOUS
from dual~', false);
    check_query(q'~p4 Anomalies per day by kind / Anomalies~', q'~with c_cont as (select c001 db_pdb, c002 db_name, c003 con_name, c004 target_name, n001 dbid, n002 con_dbid from awrcap_probe_coll where collection_name = 'AWRCAP_CONTAINER'),
c_anom as (select c001 db, c002 kind, c003 series, c004 anomaly_kind, c005 anomaly_flag, c006 unit, c007 sev, c008 message, d001 ts, d002 obs_day, n001 value, n002 expected, n003 threshold, n004 z, n005 sev_rank, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') shift_pct, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') rate_bpd from awrcap_probe_coll where collection_name = 'AWRCAP_ANOMALIES')
select a.ts, count(*) value, a.anomaly_kind name from c_anom a where ((:P0_DB is null or a.db = :P0_DB) and (:P0_TARGET is null or a.db in (select t.db_pdb from c_cont t where t.target_name = :P0_TARGET))) and a.ts between nvl(to_date(:P0_FROM default null on conversion error, 'YYYY-MM-DD'), a.ts) and nvl(to_date(:P0_TO default null on conversion error, 'YYYY-MM-DD'), a.ts) and (:P0_KIND is null or a.anomaly_kind = :P0_KIND) and (:P0_SEV is null or a.sev = :P0_SEV) group by a.ts, a.anomaly_kind order by a.ts~', p_demo);
    check_query(q'~p4 Most anomalous series / Anomalies~', q'~with c_cont as (select c001 db_pdb, c002 db_name, c003 con_name, c004 target_name, n001 dbid, n002 con_dbid from awrcap_probe_coll where collection_name = 'AWRCAP_CONTAINER'),
c_anom as (select c001 db, c002 kind, c003 series, c004 anomaly_kind, c005 anomaly_flag, c006 unit, c007 sev, c008 message, d001 ts, d002 obs_day, n001 value, n002 expected, n003 threshold, n004 z, n005 sev_rank, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') shift_pct, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') rate_bpd from awrcap_probe_coll where collection_name = 'AWRCAP_ANOMALIES')
select a.db || ' ' || a.series label, count(*) value from c_anom a where ((:P0_DB is null or a.db = :P0_DB) and (:P0_TARGET is null or a.db in (select t.db_pdb from c_cont t where t.target_name = :P0_TARGET))) and a.ts between nvl(to_date(:P0_FROM default null on conversion error, 'YYYY-MM-DD'), a.ts) and nvl(to_date(:P0_TO default null on conversion error, 'YYYY-MM-DD'), a.ts) and (:P0_KIND is null or a.anomaly_kind = :P0_KIND) and (:P0_SEV is null or a.sev = :P0_SEV) group by a.db, a.series order by count(*) desc, 1 fetch first 10 rows only~', false);
    check_query(q'~p4 Anomaly timeline / Anomalies~', q'~with c_cont as (select c001 db_pdb, c002 db_name, c003 con_name, c004 target_name, n001 dbid, n002 con_dbid from awrcap_probe_coll where collection_name = 'AWRCAP_CONTAINER'),
c_anom as (select c001 db, c002 kind, c003 series, c004 anomaly_kind, c005 anomaly_flag, c006 unit, c007 sev, c008 message, d001 ts, d002 obs_day, n001 value, n002 expected, n003 threshold, n004 z, n005 sev_rank, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') shift_pct, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') rate_bpd from awrcap_probe_coll where collection_name = 'AWRCAP_ANOMALIES')
select e.db || ' ' || e.series || ': ' || e.anomaly_kind || case when e.n > 1 then ' (' || e.n || ' days)' end task_name, e.db || '|' || e.series || '|' || e.anomaly_kind || '|' || to_char(e.start_date, 'YYYYMMDD') task_id, e.start_date, e.end_date, e.anomaly_kind kind, nvl(to_date(:P0_FROM default null on conversion error, 'YYYY-MM-DD'), min(e.start_date) over ()) gantt_start, nvl(to_date(:P0_TO default null on conversion error, 'YYYY-MM-DD'), max(e.end_date) over ()) gantt_end
from (select a.db, a.series, a.anomaly_kind, min(a.ts) start_date, max(nvl(a.obs_day, a.ts)) + 1 end_date, count(*) n from (select a.*, a.ts - dense_rank() over (partition by a.db, a.series, a.anomaly_kind order by a.ts) grp from c_anom a where ((:P0_DB is null or a.db = :P0_DB) and (:P0_TARGET is null or a.db in (select t.db_pdb from c_cont t where t.target_name = :P0_TARGET))) and a.ts between nvl(to_date(:P0_FROM default null on conversion error, 'YYYY-MM-DD'), a.ts) and nvl(to_date(:P0_TO default null on conversion error, 'YYYY-MM-DD'), a.ts) and (:P0_KIND is null or a.anomaly_kind = :P0_KIND) and (:P0_SEV is null or a.sev = :P0_SEV)) a group by a.db, a.series, a.anomaly_kind, a.grp) e
order by e.db, e.series, e.start_date~', false);
    check_query(q'~p4 Anomalies~', q'~with c_cont as (select c001 db_pdb, c002 db_name, c003 con_name, c004 target_name, n001 dbid, n002 con_dbid from awrcap_probe_coll where collection_name = 'AWRCAP_CONTAINER'),
c_anom as (select c001 db, c002 kind, c003 series, c004 anomaly_kind, c005 anomaly_flag, c006 unit, c007 sev, c008 message, d001 ts, d002 obs_day, n001 value, n002 expected, n003 threshold, n004 z, n005 sev_rank, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') shift_pct, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') rate_bpd from awrcap_probe_coll where collection_name = 'AWRCAP_ANOMALIES')
select a.ts DAY, a.obs_day END_DAY, (select max(t.target_name) from c_cont t where t.db_pdb = a.db) TARGET, a.db DB, ('f?p=' || (case a.kind when 'TBSPC' then 2 else 3 end) || ':P0_DB:' || a.db) DB_URL, a.series SERIES, ('f?p=' || (case a.kind when 'TBSPC' then 2 else 3 end) || ':P0_DB,P0_TBSPC:' || a.db || ',' || case when a.kind = 'TBSPC' then a.db || '|' || a.series end) SERIES_URL, a.anomaly_kind ANOMALY_KIND, a.sev SEV, case a.sev when 'CRIT' then 't-Badge--danger' when 'WARN' then 't-Badge--warning' when 'INFO' then 't-Badge--info' else 't-Badge--success' end SEV_CSS, a.anomaly_flag FLAG, round(a.value, 2) VALUE, round(a.expected, 2) EXPECTED, round(a.threshold, 2) THRESHOLD, round(a.z, 1) Z, round(a.shift_pct, 1) SHIFT_PCT, case lower(a.unit) when 'io_per_sec' then 'requests/s' when 'mb_per_sec' then 'MB/s' else a.unit end UNIT, a.message MESSAGE
from c_anom a where ((:P0_DB is null or a.db = :P0_DB) and (:P0_TARGET is null or a.db in (select t.db_pdb from c_cont t where t.target_name = :P0_TARGET))) and a.ts between nvl(to_date(:P0_FROM default null on conversion error, 'YYYY-MM-DD'), a.ts) and nvl(to_date(:P0_TO default null on conversion error, 'YYYY-MM-DD'), a.ts) and (:P0_KIND is null or a.anomaly_kind = :P0_KIND) and (:P0_SEV is null or a.sev = :P0_SEV)~', p_demo);
    check_query(q'~p4 All alerts~', q'~with c_cont as (select c001 db_pdb, c002 db_name, c003 con_name, c004 target_name, n001 dbid, n002 con_dbid from awrcap_probe_coll where collection_name = 'AWRCAP_CONTAINER'),
c_alert as (select c001 severity, c002 kind, c003 db_pdb, c004 series_key, c005 unit, c006 message, d001 day_dt, n001 sev_rank, n002 value, n003 threshold from awrcap_probe_coll where collection_name = 'AWRCAP_ALERTS')
select a.severity SEV, case a.severity when 'CRIT' then 't-Badge--danger' when 'WARN' then 't-Badge--warning' when 'INFO' then 't-Badge--info' else 't-Badge--success' end SEV_CSS, a.sev_rank SEV_RANK, a.kind KIND, (select max(t.target_name) from c_cont t where t.db_pdb = a.db_pdb) TARGET, a.db_pdb DB, a.series_key SERIES, a.day_dt DAY, round(a.value, 2) VALUE, round(a.threshold, 2) THRESHOLD, case lower(a.unit) when 'io_per_sec' then 'requests/s' when 'mb_per_sec' then 'MB/s' else a.unit end UNIT, a.message MESSAGE
from c_alert a where ((:P0_DB is null or a.db_pdb = :P0_DB) and (:P0_TARGET is null or a.db_pdb in (select t.db_pdb from c_cont t where t.target_name = :P0_TARGET))) and (:P0_SEV is null or a.severity = :P0_SEV)
order by a.sev_rank, a.day_dt desc~', false);
  end check_page_4;
begin
  :probe_fail := 1;
  dbms_output.put_line('-- scenario defaults');
  set_state('P0_TARGET', null);
  set_state('P0_DB', null);
  set_state('P0_TBSPC', null);
  set_state('P0_FROM', null);
  set_state('P0_TO', null);
  set_state('P0_KIND', null);
  set_state('P0_SEV', null);
  load_page(1, q'~REFRESH~');
  dbms_output.put_line('page 1: ' || 'P0_TARGET=' || v('P0_TARGET') || ' ' || 'P0_DB=' || v('P0_DB') || ' ' || 'P0_TBSPC=' || v('P0_TBSPC') || ' ' || 'P0_FROM=' || v('P0_FROM') || ' ' || 'P0_TO=' || v('P0_TO') || ' ' || 'P0_KIND=' || v('P0_KIND') || ' ' || 'P0_SEV=' || v('P0_SEV'));
  check_page_1(true);
  load_page(5, null);
  dbms_output.put_line('page 5: ' || 'P0_TARGET=' || v('P0_TARGET') || ' ' || 'P0_DB=' || v('P0_DB') || ' ' || 'P0_TBSPC=' || v('P0_TBSPC') || ' ' || 'P0_FROM=' || v('P0_FROM') || ' ' || 'P0_TO=' || v('P0_TO') || ' ' || 'P0_KIND=' || v('P0_KIND') || ' ' || 'P0_SEV=' || v('P0_SEV'));
  check_page_5(true);
  load_page(2, null);
  dbms_output.put_line('page 2: ' || 'P0_TARGET=' || v('P0_TARGET') || ' ' || 'P0_DB=' || v('P0_DB') || ' ' || 'P0_TBSPC=' || v('P0_TBSPC') || ' ' || 'P0_FROM=' || v('P0_FROM') || ' ' || 'P0_TO=' || v('P0_TO') || ' ' || 'P0_KIND=' || v('P0_KIND') || ' ' || 'P0_SEV=' || v('P0_SEV'));
  check_page_2(true);
  load_page(3, null);
  dbms_output.put_line('page 3: ' || 'P0_TARGET=' || v('P0_TARGET') || ' ' || 'P0_DB=' || v('P0_DB') || ' ' || 'P0_TBSPC=' || v('P0_TBSPC') || ' ' || 'P0_FROM=' || v('P0_FROM') || ' ' || 'P0_TO=' || v('P0_TO') || ' ' || 'P0_KIND=' || v('P0_KIND') || ' ' || 'P0_SEV=' || v('P0_SEV'));
  check_page_3(true);
  load_page(6, null);
  dbms_output.put_line('page 6: ' || 'P0_TARGET=' || v('P0_TARGET') || ' ' || 'P0_DB=' || v('P0_DB') || ' ' || 'P0_TBSPC=' || v('P0_TBSPC') || ' ' || 'P0_FROM=' || v('P0_FROM') || ' ' || 'P0_TO=' || v('P0_TO') || ' ' || 'P0_KIND=' || v('P0_KIND') || ' ' || 'P0_SEV=' || v('P0_SEV'));
  check_page_6(true);
  load_page(4, null);
  dbms_output.put_line('page 4: ' || 'P0_TARGET=' || v('P0_TARGET') || ' ' || 'P0_DB=' || v('P0_DB') || ' ' || 'P0_TBSPC=' || v('P0_TBSPC') || ' ' || 'P0_FROM=' || v('P0_FROM') || ' ' || 'P0_TO=' || v('P0_TO') || ' ' || 'P0_KIND=' || v('P0_KIND') || ' ' || 'P0_SEV=' || v('P0_SEV'));
  check_page_4(true);
  dbms_output.put_line('-- scenario one-db');
  set_state('P0_TARGET', null);
  set_state('P0_DB', pick(q'~with c_fit as (select c001 db, c002 kind, c003 series, c004 unit, c005 method, c006 quality, c007 sev, c008 limit_source, d001 last_day, n001 value, n002 limit_value, n003 pct, n004 days_to_full, n005 sev_rank, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') slope_per_day, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') r2, to_number(c011, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') days_to_full_lo, to_number(c012, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') days_to_full_hi, to_number(c013, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') accel, to_number(c014, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') train_n from awrcap_probe_coll where collection_name = 'AWRCAP_FIT')
