  check_empty(q'~AWRCAP_ANOMALIES~', q'~with c_anom as (select c001 db, c002 kind, c003 series, c004 anomaly_kind, c005 anomaly_flag, c006 unit, c007 sev, c008 message, d001 ts, d002 obs_day, n001 value, n002 expected, n003 threshold, n004 z, n005 sev_rank, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') shift_pct, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') rate_bpd from awrcap_probe_coll where collection_name = 'AWRCAP_ANOMALIES')
select * from ((select db, kind, series, anomaly_kind, anomaly_flag, unit, sev, message, ts, obs_day, round(value, 10), round(expected, 10), round(threshold, 10), round(z, 10), round(sev_rank, 10), round(shift_pct, 10), round(rate_bpd, 10) from c_anom minus select db, kind, series, anomaly_kind, anomaly_flag, unit, sev, message, ts, obs_day, round(value, 10), round(expected, 10), round(threshold, 10), round(z, 10), round(sev_rank, 10), round(shift_pct, 10), round(rate_bpd, 10) from (select * from capr_anomalies))
union all (select db, kind, series, anomaly_kind, anomaly_flag, unit, sev, message, ts, obs_day, round(value, 10), round(expected, 10), round(threshold, 10), round(z, 10), round(sev_rank, 10), round(shift_pct, 10), round(rate_bpd, 10) from (select * from capr_anomalies) minus select db, kind, series, anomaly_kind, anomaly_flag, unit, sev, message, ts, obs_day, round(value, 10), round(expected, 10), round(threshold, 10), round(z, 10), round(sev_rank, 10), round(shift_pct, 10), round(rate_bpd, 10) from c_anom))~');
  check_empty(q'~AWRCAP_ALERTS~', q'~with c_alert as (select c001 severity, c002 kind, c003 db_pdb, c004 series_key, c005 unit, c006 message, d001 day_dt, n001 sev_rank, n002 value, n003 threshold from awrcap_probe_coll where collection_name = 'AWRCAP_ALERTS')
select * from ((select severity, kind, db_pdb, series_key, unit, message, day_dt, round(sev_rank, 10), round(value, 10), round(threshold, 10) from c_alert minus select severity, kind, db_pdb, series_key, unit, message, day_dt, round(sev_rank, 10), round(value, 10), round(threshold, 10) from (select * from capr_alerts))
union all (select severity, kind, db_pdb, series_key, unit, message, day_dt, round(sev_rank, 10), round(value, 10), round(threshold, 10) from (select * from capr_alerts) minus select severity, kind, db_pdb, series_key, unit, message, day_dt, round(sev_rank, 10), round(value, 10), round(threshold, 10) from c_alert))~');
  check_empty(q'~AWRCAP_MEM_VERDICT~', q'~with c_memv as (select c001 db_pdb, c002 area, c003 area_label, c004 mem_mode, c005 grade, c006 reason, c007 reason_text, c008 actionable, c009 current_size, c010 suggested_size, c011 suggested_param, c012 exceeds_host_ram, c013 exceeds_sga, c014 headline, d001 window_start, d002 window_end, n001 instance_number, n002 area_rank, n003 current_bytes, n004 suggested_bytes, n005 change_pct, to_number(c015, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') n_evidence, to_number(c016, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') n_pressure, to_number(c017, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') n_days, to_number(c018, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') rank_mem from awrcap_probe_coll where collection_name = 'AWRCAP_MEM_VERDICT')
select * from ((select db_pdb, area, area_label, mem_mode, grade, reason, reason_text, actionable, current_size, suggested_size, suggested_param, exceeds_host_ram, exceeds_sga, headline, window_start, window_end, round(instance_number, 10), round(area_rank, 10), round(current_bytes, 10), round(suggested_bytes, 10), round(change_pct, 10), round(n_evidence, 10), round(n_pressure, 10), round(n_days, 10), round(rank_mem, 10) from c_memv minus select db_pdb, area, area_label, mem_mode, grade, reason, reason_text, actionable, current_size, suggested_size, suggested_param, exceeds_host_ram, exceeds_sga, headline, window_start, window_end, round(instance_number, 10), round(area_rank, 10), round(current_bytes, 10), round(suggested_bytes, 10), round(change_pct, 10), round(n_evidence, 10), round(n_pressure, 10), round(n_days, 10), round(rank_mem, 10) from (select * from capr_mem_verdict))
union all (select db_pdb, area, area_label, mem_mode, grade, reason, reason_text, actionable, current_size, suggested_size, suggested_param, exceeds_host_ram, exceeds_sga, headline, window_start, window_end, round(instance_number, 10), round(area_rank, 10), round(current_bytes, 10), round(suggested_bytes, 10), round(change_pct, 10), round(n_evidence, 10), round(n_pressure, 10), round(n_days, 10), round(rank_mem, 10) from (select * from capr_mem_verdict) minus select db_pdb, area, area_label, mem_mode, grade, reason, reason_text, actionable, current_size, suggested_size, suggested_param, exceeds_host_ram, exceeds_sga, headline, window_start, window_end, round(instance_number, 10), round(area_rank, 10), round(current_bytes, 10), round(suggested_bytes, 10), round(change_pct, 10), round(n_evidence, 10), round(n_pressure, 10), round(n_days, 10), round(rank_mem, 10) from c_memv))~');
  check_empty(q'~AWRCAP_MEM_EVIDENCE~', q'~with c_meme as (select c001 db_pdb, c002 area, c003 area_label, c004 kind, c005 signal, c006 direction, c007 unit, c008 evidence_text, d001 observed_at, n001 instance_number, n002 area_rank, n003 value, n004 threshold, n005 rank_ev from awrcap_probe_coll where collection_name = 'AWRCAP_MEM_EVIDENCE')
select * from ((select db_pdb, area, area_label, kind, signal, direction, unit, evidence_text, observed_at, round(instance_number, 10), round(area_rank, 10), round(value, 10), round(threshold, 10), round(rank_ev, 10) from c_meme minus select db_pdb, area, area_label, kind, signal, direction, unit, evidence_text, observed_at, round(instance_number, 10), round(area_rank, 10), round(value, 10), round(threshold, 10), round(rank_ev, 10) from (select * from capr_mem_evidence))
union all (select db_pdb, area, area_label, kind, signal, direction, unit, evidence_text, observed_at, round(instance_number, 10), round(area_rank, 10), round(value, 10), round(threshold, 10), round(rank_ev, 10) from (select * from capr_mem_evidence) minus select db_pdb, area, area_label, kind, signal, direction, unit, evidence_text, observed_at, round(instance_number, 10), round(area_rank, 10), round(value, 10), round(threshold, 10), round(rank_ev, 10) from c_meme))~');
  check_empty(q'~AWRCAP_MEM_POINTS~', q'~with c_memp as (select c001 db_pdb, c002 component, d001 ts, n001 instance_number, n002 bytes, n003 min_bytes, n004 max_bytes, n005 ops from awrcap_probe_coll where collection_name = 'AWRCAP_MEM_POINTS')
select * from ((select db_pdb, component, ts, round(instance_number, 10), round(bytes, 10), round(min_bytes, 10), round(max_bytes, 10), round(ops, 10) from c_memp minus select db_pdb, component, ts, round(instance_number, 10), round(bytes, 10), round(min_bytes, 10), round(max_bytes, 10), round(ops, 10) from (select p.instance_number, p.component, p.ts, p.bytes, p.min_bytes, p.max_bytes, p.ops, nvl(c.db_pdb, to_char(p.dbid)) db_pdb from capr_mem_comp_points p left join capr_container c on c.dbid = p.dbid and c.con_dbid = p.con_dbid))
union all (select db_pdb, component, ts, round(instance_number, 10), round(bytes, 10), round(min_bytes, 10), round(max_bytes, 10), round(ops, 10) from (select p.instance_number, p.component, p.ts, p.bytes, p.min_bytes, p.max_bytes, p.ops, nvl(c.db_pdb, to_char(p.dbid)) db_pdb from capr_mem_comp_points p left join capr_container c on c.dbid = p.dbid and c.con_dbid = p.con_dbid) minus select db_pdb, component, ts, round(instance_number, 10), round(bytes, 10), round(min_bytes, 10), round(max_bytes, 10), round(ops, 10) from c_memp))~');
  check_empty(q'~AWRCAP_META~', q'~with c_meta as (select n001 cpu_sat_pct, n002 dtf_warn, n003 dtf_crit, n004 nearfull_warn_pct, n005 nearfull_crit_pct, to_number(c001, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') series_sat_pct, to_number(c002, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') anomaly_report_days, d001 loaded_at from awrcap_probe_coll where collection_name = 'AWRCAP_META')
select * from ((select round(cpu_sat_pct, 10), round(dtf_warn, 10), round(dtf_crit, 10), round(nearfull_warn_pct, 10), round(nearfull_crit_pct, 10), round(series_sat_pct, 10), round(anomaly_report_days, 10) from c_meta minus select round(cpu_sat_pct, 10), round(dtf_warn, 10), round(dtf_crit, 10), round(nearfull_warn_pct, 10), round(nearfull_crit_pct, 10), round(series_sat_pct, 10), round(anomaly_report_days, 10) from (select max(case when cfg_name = 'cpu_sat_pct' then cfg_value end) cpu_sat_pct, max(case when cfg_name = 'dtf_warn' then cfg_value end) dtf_warn, max(case when cfg_name = 'dtf_crit' then cfg_value end) dtf_crit, max(case when cfg_name = 'nearfull_warn_pct' then cfg_value end) nearfull_warn_pct, max(case when cfg_name = 'nearfull_crit_pct' then cfg_value end) nearfull_crit_pct, max(case when cfg_name = 'series_sat_pct' then cfg_value end) series_sat_pct, max(case when cfg_name = 'anomaly_report_days' then cfg_value end) anomaly_report_days , sysdate loaded_at from cap_config))
union all (select round(cpu_sat_pct, 10), round(dtf_warn, 10), round(dtf_crit, 10), round(nearfull_warn_pct, 10), round(nearfull_crit_pct, 10), round(series_sat_pct, 10), round(anomaly_report_days, 10) from (select max(case when cfg_name = 'cpu_sat_pct' then cfg_value end) cpu_sat_pct, max(case when cfg_name = 'dtf_warn' then cfg_value end) dtf_warn, max(case when cfg_name = 'dtf_crit' then cfg_value end) dtf_crit, max(case when cfg_name = 'nearfull_warn_pct' then cfg_value end) nearfull_warn_pct, max(case when cfg_name = 'nearfull_crit_pct' then cfg_value end) nearfull_crit_pct, max(case when cfg_name = 'series_sat_pct' then cfg_value end) series_sat_pct, max(case when cfg_name = 'anomaly_report_days' then cfg_value end) anomaly_report_days , sysdate loaded_at from cap_config) minus select round(cpu_sat_pct, 10), round(dtf_warn, 10), round(dtf_crit, 10), round(nearfull_warn_pct, 10), round(nearfull_crit_pct, 10), round(series_sat_pct, 10), round(anomaly_report_days, 10) from c_meta))~');
  for c in (select collection_name, count(*) n from awrcap_probe_coll group by collection_name order by 1) loop
    dbms_output.put_line('collection ' || rpad(c.collection_name, 20) || lpad(c.n, 7));
  end loop;
  :probe_fail := l_fail;
  dbms_output.put_line('RESULT: apex probe ' || l_pass || ' passed, ' || l_fail || ' failed');
exception when others then
  dbms_output.put_line('FAIL  probe aborted: ' || sqlerrm);
end;
/
drop table awrcap_probe_coll purge;
begin
  if :probe_fail > 0 then
    raise_application_error(-20001, 'apex probe: ' || :probe_fail || ' check(s) failed');
  end if;
  dbms_output.put_line('apex probe: all checks passed');
end;
/
